INSERT INTO `articles` (`id`, `slug`, `title`, `dek`, `body`, `cover_url`, `cover_credit`, `category_id`, `author_id`, `created_by`, `status`, `published_at`, `location`, `reading_minutes`, `is_featured`, `is_breaking`, `seo_title`, `seo_description`, `view_count`, `share_count`, `created_at`, `updated_at`) VALUES
('0c742a81-6255-490d-93d4-eb1b69025ddb', 'fact-check-jacques-kongolo-est-il-un-agent-du-rwanda-comme-laffirment-certains-messages-en-ligne-voici-les-faits', 'Fact-check: Jacques Kongolo est-il un « agent du Rwanda » comme l’affirment certains messages en ligne ? Voici les faits', 'Depuis plusieurs jours, des publications circulant sur les réseaux sociaux accusent Jacques Kongolo, chargé de mission du président de la République démocratique du Congo suivi des questions communautaires et identitaires dans la partie orientale du pays, d’être un « agent du…', 'Depuis plusieurs jours, des publications circulant sur les réseaux sociaux accusent Jacques Kongolo, chargé de mission du président de la République démocratique du Congo suivi des questions communautaires et identitaires dans la partie orientale du pays, d’être un « agent du Rwanda » qui percevrait encore un salaire de l’administration rwandaise.\n\nCes accusations apparaissent dans un contexte de tensions persistantes entre la République démocratique du Congo et le Rwanda, accusé de soutenir la rébellion du M23.\n\nNous avons examiné ces affirmations\n\nL’infox\n\nSelon plusieurs publications relayées sur X et Facebook, Jacques Kongolo serait en réalité un citoyen rwandais qui continuerait à percevoir un salaire comme « agent d’Umwirondoro », une entité administrative au Rwanda.\n\nCes messages affirment également que son père aurait été chef dans la région de Kayonza et que ces informations seraient « numérisées dans l’administration rwandaise ». Les auteurs insinuent ainsi que Kongolo agirait au sein des institutions congolaises tout en restant lié à l’État rwandais.\n\nAucune preuve ou document officiel n’est toutefois fourni pour étayer ces accusations.\n\nCe que l’on sait de l’identité et du parcours de Jacques Kongolo\n\nLes éléments biographiques disponibles situent l’origine de Jacques Kongolo dans l’espace congolais.\n\nIl est né dans la zone d’administration de Vyura/Kingungwa, dans la collectivité de Tumbwe, groupement Fatuma, territoire de Kalemie, dans l’actuelle province du Tanganyika. À l’époque de sa naissance, cette région faisait partie du grand Katanga, dans la République démocratique du Congo.\n\nSes deux parents sont originaires du territoire de Fizi, dans la province du Sud-Kivu.\n\nSelon plusieurs témoignages locaux, son père fait partie des premiers membres de la communauté Banyamulenge à s’être mariés à Vyura dans le secteur du Tanganyika.\n\nSon grand-père, Joël Mutabazi, est présenté comme le premier pasteur de l’Église Méthodiste Unie à Vyura, ce qui témoigne d’une présence ancienne de la famille dans cette région.\n\nLe témoignage d’un ami d’enfance\n\nDes détails sur l’enfance et la scolarité de Jacques Kongolo sont également confirmés par Kitungwa Pacifique, un ami d’enfance ayant grandi avec lui dans la région.\n\nSelon ce dernier, Kongolo a fréquenté :\n\n• l’école primaire de Kabutonga, dirigée à l’époque par Ngoyi Kalowa.\n\n• son enseignante de la première primaire s’appelait Kasongo à l’école, connue dans la localité.\n\n• puis l’Institut Vyura pour le cycle inférieur de ses études secondaires.\n\n« Nous avons grandi ensemble et étudié dans les mêmes écoles. Son père était proposé de remplacer son oncle paternel qui était le chef de localité Kingungwa. D’ailler même le grand père de sa mère était chef coutumier du secteur de Tanganyika avant qu’il ne se déplace vers Vyura », explique Kitungwa Pacifique, qui affirme également se souvenir des autorités locales de l’époque, notamment le chef de localité Kingungwa, le chef de groupement Fatuma et l’administration de la collectivité de Tumbwe dans le territoire de Kalemie.\n\nCes témoignages situent le parcours de Kongolo dans le contexte administratif et social congolais.\n\n« Je n’ai jamais travaillé au Rwanda, la dernière fois que j’ai été dans ce pays c’était en 2010, j’étais en transit pour l’Éthiopie », a déclaré brièvement Jacques Kongolo.\n\nPourquoi Jacques Kongolo est aujourd’hui ciblé\n\nPlusieurs éléments permettent de comprendre pourquoi cette personnalité est devenue la cible d’attaques sur les réseaux sociaux.\n\nUne nomination symbolique\n\nJacques Kongolo est considéré comme le premier membre de la communauté Banyamulenge nommé par ordonnance présidentielle comme chargé de mission du chef de l’État pour les questions communautaires et identitaires dans l’Est du pays.\n\nAvant lui, Azarias Ruberwa avait occupé des fonctions importantes au sommet de l’État après le Dialogue intercongolais de Sun City, qui avait intégré plusieurs mouvements rebelles dans les institutions congolaises.\n\nSes dénonciations de l’implication rwandaise\n\nJacques Kongolo fait partie des personnalités Banyamulenge qui dénoncent publiquement des incursions de l’armée rwandaise dans certaines zones de l’est de la RDC, notamment autour de Minembwe et dans plusieurs localités du Sud-Kivu.\n\nCes prises de position vont à l’encontre du discours défendu par Kigali sur le conflit dans la région.\n\nSon rôle dans la médiation communautaire\n\nDans le cadre d’une mission confiée par le président Félix Tshisekedi, Kongolo s’est rendu à plusieurs reprises dans les territoires de Fizi et Uvira pour tenter de réduire les tensions entre communautés.\n\nIl a rencontré des leaders locaux ainsi que certains responsables de groupes armés afin de promouvoir la coexistence pacifique.\n\nParmi eux figure le chef rebelle Amuri Yakutumba, qui a depuis appelé publiquement les communautés de la région à vivre ensemble.\n\nKongolo s’est également déplacé dans plusieurs zones sensibles, notamment Makobola, Kigongo et les lignes de front autour d’Uvira, pour soutenir les initiatives de paix et encourager les forces engagées dans la défense du territoire.\n\nDes démarches diplomatiques à l’international\n\nJacques Kongolo a également participé à des démarches diplomatiques visant à expliquer la position de Kinshasa sur la crise sécuritaire dans l’est du pays et sur la présence présumée de forces rwandaises en RDC.\n\nIl a notamment rencontré des responsables américains, européens et qataris.\n\nÀ Doha, il a pris part à des discussions liées à un protocole d’échange de prisonniers entre le gouvernement congolais, la rébellion du M23 et le Comité international de la Croix-Rouge.\n\nAinsi donc, aucune preuve publique ne permet de confirmer les affirmations selon lesquelles Jacques Kongolo percevrait un salaire du Rwanda ou serait un agent de l’administration rwandaise.\n\nIl est connu et célèbre même quand il était en Éthiopie, il s’est engagé pour lutter contre l’usurpation d’identité faite par certains Rwandais qui cherchaient à aller en exil. Ils utilisaient ces identités congolaises de Banyamulenge.\n\nKongo a passé sa vie chez l’ancien gouverneur Norbert Basengezi Katindtima.\n\nLes publications à l’origine de cette accusation ne fournissent ni documents officiels ni sources vérifiables.\n\nDans le contexte de la guerre informationnelle entourant le conflit dans l’est de la République démocratique du Congo, ces accusations s’apparentent davantage à une tentative de discrédit visant une personnalité engagée dans les initiatives de médiation et dans la dénonciation de l’implication rwandaise dans la région.\n\nDaniel Michombero', '/__l5e/assets-v1/1421df1f-e7b6-44f4-af4a-ed9ab2d8179e/IMG-20260315-WA0015.jpg', NULL, '65df35f4-289f-4a06-8b4d-8e3c510c68d3', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2026-03-15 13:07:12', NULL, 5, 0, 0, 'Fact-check: Jacques Kongolo est-il un « agent du Rwanda » co', 'Depuis plusieurs jours, des publications circulant sur les réseaux sociaux accusent Jacques Kongolo, chargé de mission du président de la République démocr', 0, 0, '2026-08-02 11:23:55', '2026-08-04 16:32:18'),
('6341ba1c-5c08-4cca-8444-7b6c94e9aad0', 'fact-check-lafc-m23-na-pas-electrifie-les-zones-occupees-et-na-pas-commande-le-transformateur', 'Fact check: l’AFC/M23 n’a pas électrifié les zones occupées et n’a pas commandé le transformateur', 'Depuis ce lundi 27 octobre 2025, un post du vice-gouverneur rebelle Willy Manzi circule sur les réseaux sociaux. Il y affirme que l’AFC/M23 a électrifié toutes les zones sous son contrôle au Nord-Kivu et qu’un nouveau transformateur électrique « a désormais la capacité…', 'Depuis ce lundi 27 octobre 2025, un post du vice-gouverneur rebelle Willy Manzi circule sur les réseaux sociaux. Il y affirme que l’AFC/M23 a électrifié toutes les zones sous son contrôle au Nord-Kivu et qu’un nouveau transformateur électrique « a désormais la capacité d’alimenter toute la région ». Selon lui, « l’obscurité dans les zones contrôlées sera bientôt une chose du passé, grâce à la bonne gouvernance et à l’esprit d’innovation de l’AFC/M23 ». C’est une fausse information après vérification faite par Reelactu.\n\nQui est Willy Manzi ?\n\nWilly Manzi est un rebelle du M23 qui occupe la fonction de vice-gouverneur dans une partie du Nord-Kivu sous contrôle du mouvement. Ses déclarations ne reflètent pas l’action officielle de l’État congolais ni celle de projets techniques crédibles, mais relèvent de la communication d’un acteur armé sur une zone partiellement occupée.\n\nPour vérifier ces allégations, Reelactu a consulté les documents officiels du projet d’interconnexion électrique régional, financé par la Banque africaine de développement (BAD) dans le cadre du programme NELSAP, et contacté des sources proches du projet.\n\nVous pouvez également accéder à ce projet en cliquant sur ce lien\n\nIl s’agit plutôt d’un projet régional qui vise la construction et le renforcement de 769 km de lignes électriques en 220 kV et 10 kV, et de 17 postes de transformation, pour interconnecter les réseaux électriques du Burundi, Kenya, Ouganda, RDC et Rwanda. L’objectif est d’améliorer la disponibilité d’une énergie électrique abordable, soutenir le développement économique et social de la région, et faciliter les échanges transfrontaliers d’énergie. Le coût global du projet initial était estimé à plus 160,20 millions de dollars américains, un achèvement etait prévu fin 2017 mais le projet a connu des retards.\n\nComposante RDC : Après la revue à mi-parcours, la RDC se concentre sur la construction de 108 km de lignes 220 kV et 2 postes de transformation. Un transformateur géant est arrivé à Goma fin août 2025, en provenance du port de Dar es-Salam via le Rwanda. Un autre est attendu car 2 au total doivent être installés pour alimenter les provinces de l’Est de la RDC dont le Nord-Kivu, le Sud-Kivu et l’Ituri. Dans cette vidéo vous pouvez voir l’avancement des activités sur le site dé Mugunga à l’Ouest de la ville de Goma où le central sera installé.\n\n/api/public/media/legacy/2025/10/fact-check-afc-m23-transformateur.mp4\n\nPendant ce temps, le programme NELSAP poursuit ses activités dans la ville de Goma, au Quartier Mugunga, où ces deux transformateurs géants seront installés pour alimenter progressivement les provinces de l’Est de la RDC.\n\nÉvaluation des besoins : Les taux d’accès à l’électricité dans la région restent faibles, entre 2 % et 17 % ; en RDC, il est de 4 %. Le Nord-Kivu et le Sud-Kivu cumulent une demande non satisfaite de 115 MW et subissent des ruptures fréquentes de fourniture électrique. Même avec le transformateur à Goma, l’accès à l’électricité reste limité et ne concerne pas toutes les zones sous contrôle de l’AFC/M23.\n\nValeur ajoutée de la Banque : La BAD a tiré des leçons de l’exécution du projet initial pour mieux ajuster les composantes révisées. Elle a également facilité le maintien des autres bailleurs et le suivi du financement du projet.\n\nGestion et suivi : La cellule d’exécution du projet fournit des rapports périodiques sur l’évolution des indicateurs, incluant supervision, contrôle des travaux par l’Ingénieur Conseil et audit financier. Ces mécanismes garantissent que le projet avance selon des standards techniques et institutionnels, loin de toute intervention d’un acteur armé.\n\nDes contraintes persistent\n\nLes travaux ont subi des retards dus à la sécurité et aux procédures administratives. L’installation d’un transformateur ne garantit pas une électrification instantanée et totale des zones contrôlées par l’AFC/M23. L’achèvement des lignes, le développement des réseaux locaux et la maintenance restent nécessaires pour améliorer l’accès à l’électricité.\n\nConclusion\n\nContrairement aux déclarations de Willy Manzi, l’AFC/M23 n’a pas électrifié toutes les zones sous son contrôle au Nord-Kivu et n’a pas commandé le transformateur. Les avancées techniques observées à Goma résultent d’un projet régional long, multilatéral et institutionnel, financé et suivi par la BAD, NELSAP et la SNEL, et non d’une action unilatérale d’un mouvement armé. Les transformateurs seront installés à Mugunga dans le cadre de ce projet régional pour alimenter progressivement les provinces de l’Est de la RDC.\n\nDaniel Michombero', '/__l5e/assets-v1/f11cbef7-89cd-4666-a5ad-eed5a04fa954/WhatsApp-Image-2025-10-28-at-10.19.18-AM.jpeg', NULL, '65df35f4-289f-4a06-8b4d-8e3c510c68d3', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2025-10-28 15:17:12', NULL, 4, 0, 0, 'Fact check: l’AFC/M23 n’a pas électrifié les zones occupées ', 'Depuis ce lundi 27 octobre 2025, un post du vice-gouverneur rebelle Willy Manzi circule sur les réseaux sociaux. Il y affirme que l’AFC/M23 a électrifié to', 0, 0, '2026-08-02 11:23:55', '2026-08-04 16:32:18'),
('8e86f548-e43a-4ab3-84c1-0edd94def1eb', 'est-de-la-rdc-une-feuille-de-route-validee-pour-la-restauration-de-lautorite-de-letat', 'Est de la RDC: Une feuille de route validée pour la restauration de l’autorité de l’Etat.', 'La restauration de l’autorité de l’Etat dans les zones affectées par l’occupation rebelle de l’ AFC/M23/RDF à eté au centre des discussions des acteurs étatatiques sous l’initiative du Vice-Premier Ministre de l’Interieur, décentralisation et affaire coutumières. Durant 2 jours…', 'La restauration de l’autorité de l’Etat dans les zones affectées par l’occupation rebelle de l’ AFC/M23/RDF à eté au centre des discussions des acteurs étatatiques sous l’initiative du Vice-Premier Ministre de l’Interieur, décentralisation et affaire coutumières.\n\nDurant 2 jours et cloturé ce samedi 24 janvier 2025 à Kinshasa, ces acteurs ont largement discutés sur les aspects globaux de la restauration de l’Etat de ces entités sous l’occupation rebelle depuis maintenant 4 ans.\n\nA l’issue des travaux intenses, une feuille de route pour la restauration de l’autorité de l’etat a été validée à en croire l’organisateur « j’ai cloturé l’atelier national ayant abouti à la validation de la feuille de route pour la restauration de l’autorité de l’Etat dans Les zones affecteés par l’occupation du RDF/AFC/M23, une feuille de route qui marque une étape decisive pour la planification, l’operationalisation et la budgétisation du retour de l’administration, de la protection des populations et du retablissement de la confiance entre l’Etat et les citoyens telle qu’exprimée par les accords signés à Washington et à Doha » s’est félicité Jacquemain Shabani Lukoo, Vice-premier ministre de l’Interieur, décentralisation et affaires coutumières.\n\nIl a ajouté que ce document prévoit des mesures concrètes pour l’opérationalisation des services publics, la securisation des territoires et la réhabilitation des institutions locales.\n\nCette demarche perçue comme une réponse urgente et coordonnee en faveur des populations meurtries se tient dans un contexte des relations tendues entre Kinshasa et Kigali, les deux parties s’accusant mutuellement de ne pas respecter les clauses des accords signés à Washington et Doha l’année dernière.\n\nD’autres acteurs contactés par RéelActu s’interrogent sur l’effectivité de la mise en oeuvre de cette feuille de route dans une zone encore occupée par ces rebelles bien que la pression diplomatique s’intensifie sur elle, l’ayant poussée mi-janvier a se retirer de la ville d’Uvira\n\n» A moins que nos autorités aient un secret sur la fin de cette aggression par ses moyens que nous ignorons mais nous ne voyons pas comment ce plan peut etre mis en oeuvre tant que ces rebelles occupent encore nos entites » s’indigne un deplacé de cette guerre.\n\nUne autre indignation a eté celle des forces vives qui ont decrié le manque de consultation et participation dans ces travaux » Comment expliquer qu’on discute d’àpres guerre et donc la restauration de l’autorités de l’Etat dans nos zones sans représentants de la population qui pourait plaider toute la situation de la population en souffrance? cet isolement m’indigne » s’est inqueté un Defenseur des Droits Humain.\n\nPourtant selon une source proche des organisateurs de cet atelier, l’étape suivante réunira les acteurs sociaux clés ainsi que les autorités administratives des zones concernérs avant l’effectivité du plan proprement dit.\n\nJustin Bizimana', '/__l5e/assets-v1/661dfab5-6802-4b71-bf14-0a215574f432/fghjk-copie.jpg', NULL, '578a4dc1-5069-4500-b734-d675df9be940', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2026-01-28 06:47:04', NULL, 2, 0, 0, 'Est de la RDC: Une feuille de route validée pour la restaura', 'La restauration de l’autorité de l’Etat dans les zones affectées par l’occupation rebelle de l’ AFC/M23/RDF à eté au centre des discussions des acteurs éta', 0, 0, '2026-08-02 11:23:55', '2026-08-02 12:16:58'),
('b0ba9bde-eb59-4d06-bdcf-b60888f32a17', 'shabunda-airtel-et-vodacom-abandonnent-leurs-antennes-la-population-livree-a-elle-meme', 'Shabunda: Airtel et Vodacom abandonnent leurs antennes, la population livrée à elle-même', 'Depuis près d’un an, plusieurs villages du groupement de Bamuguba-Sud, dans le territoire de Shabunda, vivent sans signal des réseaux de télécommunications Airtel et Vodacom. Une situation qui plonge des milliers d’habitants dans un isolement quasi total et suscite une vive…', 'Depuis près d’un an, plusieurs villages du groupement de Bamuguba-Sud, dans le territoire de Shabunda, vivent sans signal des réseaux de télécommunications Airtel et Vodacom. Une situation qui plonge des milliers d’habitants dans un isolement quasi total et suscite une vive indignation au sein de la population locale.\n\nSelon plusieurs sources concordantes, les responsables de ces réseaux auraient cessé d’approvisionner leurs antennes en carburant, indispensable au fonctionnement des installations dans cette partie enclavée du Sud-Kivu. À Isezya-Évari et Kigulube, le litre de carburant se négocie actuellement à 15 000 francs congolais, soit environ 300 000 francs congolais pour un bidon de 20 litres, un coût jugé excessif par les opérateurs.\n\nFace à cette déconnexion prolongée, les habitants affirment avoir tenté, à plusieurs reprises, de maintenir les antennes en activité grâce à leurs propres moyens. Des notables locaux, des enseignants ainsi que d’autres membres de la communauté auraient contribué financièrement à l’achat de carburant afin de permettre à la population de continuer à communiquer et d’effectuer certaines opérations financières via le téléphone mobile, notamment le retrait des salaires.\n\n« Pendant un certain temps, ce sont les habitants eux-mêmes qui alimentaient les antennes, tandis que les sociétés concernées restaient silencieuses », confie un habitant de la région.\n\nLa population de Bamuguba-Sud, considérée comme l’une des entités les plus peuplées du territoire de Shabunda, dénonce ce qu’elle qualifie d’abandon injustifié. Les habitants rappellent qu’ils continuent pourtant d’acheter régulièrement des unités de communication et de consommer les services de ces opérateurs.\n\nPlusieurs citoyens s’interrogent également sur les raisons de cette situation, alors que dans certaines zones voisines affectées par l’insécurité et les conflits armés, les réseaux téléphoniques demeurent opérationnels.\n\nActuellement, Bamuguba-Sud ainsi qu’une partie du groupement de Baliga dépendent essentiellement de connexions Wi-Fi privées pour accéder à Internet. Un service jugé inaccessible pour une grande partie de la population en raison de son coût élevé. Le prix d’un gigaoctet varie entre 5 000 et 7 000 francs congolais, avec une durée d’utilisation souvent inférieure à six heures.\n\nJoint par notre rédaction, Nzila Mutuza Akrobo, habitant de Kigulube, estime que cette coupure prolongée vient aggraver des conditions de vie déjà difficiles dans cette partie du Sud-Kivu.\n\n« La population souffre déjà de la guerre à l’Est de la RDC, de la hausse des prix des produits de première nécessité ainsi que du mauvais état de la route Bukavu–Kigulube–Shabunda. Aujourd’hui, l’absence de réseau complique davantage la vie des habitants », déplore-t-il.\n\nCet habitant appelle les responsables d’Airtel et Vodacom à reprendre rapidement l’approvisionnement de leurs antennes afin de rétablir les communications dans la région. Il invite également les autorités compétentes à s’impliquer pour trouver une solution durable à cette crise qui affecte lourdement la population locale.\n\nIsaka Kijana', '/__l5e/assets-v1/10b287b9-608c-4cab-9c82-84f8d08ac0dc/20260518_125142.jpg', NULL, '88e488f2-f5d8-42f2-9929-b16c13e10693', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2026-05-18 10:58:32', NULL, 2, 0, 0, 'Shabunda: Airtel et Vodacom abandonnent leurs antennes, la p', 'Depuis près d’un an, plusieurs villages du groupement de Bamuguba-Sud, dans le territoire de Shabunda, vivent sans signal des réseaux de télécommunications', 0, 0, '2026-08-02 11:23:55', '2026-08-02 15:44:30'),
('cabccc79-87ac-4470-abc2-8caf01f8707d', 'rdc-la-haute-cour-militaire-ouvre-un-proces-visant-plusieurs-officiers-superieurs-des-fardc', 'RDC: la Haute Cour militaire ouvre un procès visant plusieurs officiers supérieurs des FARDC', 'La Haute Cour militaire de la République démocratique du Congo a inscrit à son rôle, pour l’audience publique du 4 juin 2026, une affaire mettant en cause plusieurs officiers supérieurs des Forces armées de la RDC (FARDC) ainsi qu’un civil. Selon l’extrait de rôle publié par le…', 'La Haute Cour militaire de la République démocratique du Congo a inscrit à son rôle, pour l’audience publique du 4 juin 2026, une affaire mettant en cause plusieurs officiers supérieurs des Forces armées de la RDC (FARDC) ainsi qu’un civil.\n\nSelon l’extrait de rôle publié par le greffe de la Haute Cour militaire, le ministère public, représenté par l’Auditeur général près cette juridiction, poursuit dix prévenus, dont d’anciens hauts responsables militaires.\n\nParmi les personnes citées figurent le général d’armée Christian Tshiwewe Songesha, le général John Numbi Banza Ntambo, le général-major Maurice Nyembo Kufi, les généraux de brigade Chinyabuuma Kamukinde, John Noy wa Kabila et John Sangwa Muhemedi, ainsi que les colonels Guy Mukombozi Zahinda, Pathy Sangwa Lumbu et Christophe Tshibangu Kenge. Le civil Pascal Nyembo Muyumba est également concerné par la procédure.\n\nD’après l’extrait de rôle, les prévenus sont poursuivis notamment pour complot, propagation de faux bruits, apologie du terrorisme, trahison, violation des consignes, désertion à l’étranger, détention illégale d’armes et de munitions de guerre ainsi qu’incitation de militaires à commettre des actes contraires au devoir et à la discipline.\n\nL’audience est prévue à 9 heures dans la salle habituelle des audiences de la Haute Cour militaire, située au rez-de-chaussée du nouveau Palais de justice, dans la commune de la Gombe à Kinshasa.\n\nÀ ce stade de la procédure, les personnes citées dans l’extrait de rôle bénéficient de la présomption d’innocence jusqu’à une éventuelle décision judiciaire définitive.', '/__l5e/assets-v1/e619b5f4-041a-42c5-a724-36269650bfb1/20260602_065945.jpg', NULL, '578a4dc1-5069-4500-b734-d675df9be940', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2026-06-02 05:05:10', NULL, 1, 0, 0, 'RDC: la Haute Cour militaire ouvre un procès visant plusieur', 'La Haute Cour militaire de la République démocratique du Congo a inscrit à son rôle, pour l’audience publique du 4 juin 2026, une affaire mettant en cause ', 0, 0, '2026-08-02 11:23:55', '2026-08-02 12:16:58'),
('55f681a4-1100-4ea5-8aff-b074dc36821b', 'cameroun-le-gouvernement-assure-que-paul-biya-est-vivant-et-annonce-son-retour-p', 'Cameroun : le gouvernement assure que Paul Biya est vivant et annonce son retour prochain', 'Pour la première fois depuis le départ du président camerounais Paul Biya le 7 juin dernier, un membre du gouvernement s’est exprimé publiquement afin de répondre aux interrogations grandissantes sur l’absence prolongée du chef de l’État.', 'Invité de RFI dimanche 2 août, le ministre de la Communication et porte-parole du gouvernement, René Emmanuel Sadi, a affirmé que le président de la République est « en vie » et qu’aucune procédure de vacance du pouvoir n’est engagée.\n\n« Le Conseil constitutionnel ne s’est pas prononcé pour déclarer une vacance du pouvoir à la tête de l’État. Le président Paul Biya est en vie. Le président Paul Biya n’a pas démissionné », a déclaré le ministre, rejetant ainsi les appels de plusieurs responsables de l’opposition qui demandent au Conseil constitutionnel de constater une éventuelle vacance de la présidence.\n\nInterrogé sur le lieu où séjourne actuellement le chef de l’État, René Emmanuel Sadi n’a pas souhaité apporter de précisions. « Je ne peux pas vous dire avec exactitude quand est-ce que le président Paul Biya revient. Et même si je le savais, il ne m’appartient pas de l’annoncer ici. Je peux au moins me permettre de vous dire qu’il revient très bientôt », a-t-il indiqué.\n\nÂgé de 93 ans, Paul Biya dirige le Cameroun depuis 1982, ce qui fait de lui le plus ancien chef d’État en exercice au monde. Le président avait quitté Yaoundé le 7 juin pour ce qui avait été présenté officiellement comme un « court séjour privé en Europe », accompagné de son épouse, Chantal Biya. Depuis son départ, il n’est plus apparu en public, une absence qui constitue la plus longue enregistrée depuis son accession au pouvoir.\n\nAu cours des dernières semaines, plusieurs rumeurs ont circulé concernant son état de santé, évoquant notamment une éventuelle hospitalisation à Genève, en Suisse. Ces informations avaient été officiellement démenties par le gouvernement camerounais, sans qu’aucune autorité suisse ne les confirme.\n\nMalgré l’absence du président, la présidence de la République continue de publier des actes officiels portant sa signature. La publication, le 22 juillet, de plusieurs décrets indiquant « Yaoundé » comme lieu de signature a suscité des interrogations sur les réseaux sociaux, où certains internautes ont remis en question leur authenticité.\n\nCette situation intervient également dans un contexte institutionnel particulier. En mai 2026, une révision de la Constitution a réintroduit la fonction de vice-président de la République. Plus de trois mois après l’entrée en vigueur de cette réforme, aucun titulaire n’a toutefois été nommé à ce poste, dont la désignation relève exclusivement du président de la République.\n\nFace aux interrogations soulevées par cette absence prolongée, plusieurs juristes et responsables de l’opposition ont appelé le Conseil constitutionnel à examiner la question d’une éventuelle vacance du pouvoir. De son côté, le Rassemblement démocratique du peuple camerounais (RDPC), parti au pouvoir, soutient qu’aucune disposition constitutionnelle ne fixe de durée maximale pour l’absence du chef de l’État hors du territoire national.\n\nEn l’absence d’un vice-président, la Constitution prévoit qu’en cas de vacance du pouvoir, l’intérim serait assuré par le président du Sénat, Aboubakary Abdoulaye, jusqu’à l’organisation d’une nouvelle élection présidentielle.\n\nL’absence prolongée de Paul Biya continue d’alimenter les débats politiques au Cameroun, alors que le gouvernement tente de rassurer l’opinion publique sur la continuité des institutions et le fonctionnement normal de l’État.\n', '/api/public/media/2026/4cb323d7-d172-48cf-a0f7-44234e3dd878.webp', 'Le président camerounais Paul Biya participe au Forum de Paris sur la paix, en France, le 12 novembre 2019 [Charles Platiau/Reuters]', 'a0cf52ad-61e8-4537-8f09-c2d4d8d86980', 'c4024581-a8d4-4a10-8657-43ec2b68431f', 'd0cf6ad7-a1a2-4871-871c-44b12548eea8', 'publie', '2026-08-03 16:33:26', 'Yaoundé ', 3, 0, 1, '', '', 0, 0, '2026-08-03 16:33:26', '2026-08-03 16:33:26'),
('91c18872-52d5-47ae-865e-de652316dd47', 'rdc-les-femmes-de-la-mine-les-creuseuses-sans-beche', 'RDC: Les femmes de la mine: les creuseuses sans bêche', 'Après une semaine dans différents carrés miniers au Sud-Kivu, Reelactu a rencontré des creseurs dont des femmes et leurs chefs pour comprendre ce qu’elles traversent dans ce secteur. Sur terrain, la situation est alarmante, les coutumes et traditions locales supplantent souvent…', 'Après une semaine dans différents carrés miniers au Sud-Kivu, Reelactu a rencontré des creseurs dont des femmes et leurs chefs pour comprendre ce qu’elles traversent dans ce secteur.\n\nSur terrain, la situation est alarmante, les coutumes et traditions locales supplantent souvent la loi. Dans plusieurs territoires miniers comme à Mwenga, Shabunda ou Fizi, la femme est interdite d’accès à certains carrés miniers sous prétexte qu’elle « fait fuir l’or ».\n\n« Le Code minier donne accès aux ressources aussi bien aux hommes qu’aux femmes. Mais dans la pratique, les coutumes pèsent lourdement sur nous. Ces règles ont été taillées à la mesure des hommes », explique Agnès Sadiki, de l’organisation Rien sans les Femmes.\n\nLes femmes représentent entre 20 et 50 % de la main-d’œuvre active dans les zones minières artisanales. Elles sont broyeuses, laveuses, porteuses ou récupératrices de déchets miniers, travaillant souvent dans des conditions inhumaines.\n\nPour survivre, certaines se tournent vers le petit commerce ou la restauration de fortune, d’autres tombent dans la prostitution. On les appelle avec ironie les « creuseuses sans bêche ».\n\n« Nous sommes dans la souffrance. Nous travaillons dans l’eau, les enfants n’ont plus accès à l’école, nous n’avons rien gagné malgré nos efforts », témoigne Madame Nabakanga Mwenga, twangeuse à Mwenga.\n\n« Nous nous donnons aux hommes pour nourrir nos enfants. L’eau salée dans laquelle nous travaillons nous rend malades », confie Ngaliya Sankule, 23 ans.\n\nLes femmes subissent également des fouilles corporelles humiliantes, des dettes imposées, et un harcèlement sexuel quasi institutionnalisé.\n\n« Les femmes portent des dizaines de kilos de quartz sur leur dos. D’autres broient ces pierres toute la journée, leurs paumes sont plus dures que du fer », décrit Stella Yanda, coordinatrice de l’organisation Initiatives Alpha.\n\nDepuis plus de 30 ans, l’Est de la RDC est ravagé par des conflits armés que finance en grande partie l’exploitation illégale des minerais. Les groupes armés qu’ils soient congolais ou étrangers comme le M23 contrôlent plusieurs zones minières.\n\nDans ces régions, les femmes sont doublement victimes : exploitées sexuellement et économiquement. Elles doivent parfois céder leurs corps pour obtenir le droit de travailler ou payer une « taxe » aux combattants.\n\n« Pour qu’une femme travaille ici, elle doit d’abord être exploitée sexuellement. C’est la condition d’accès », révèle Christophe Songa, superviseur au site minier de Camp Danger.\n\nL’impunité règne. L’absence d’autorités, de police et de services d’assistance fait que la plupart des cas de viols ou d’abus sont “réglés” à l’amiable, au détriment des victimes.\n\nL’exploitation minière en RDC ne peut plus être considérée comme un simple enjeu économique. Elle est aujourd’hui une question de justice, de dignité et de droits humains.\n\nLes réformes en cours du Code minier et du Code de la famille doivent impérativement intégrer la dimension genre : Reconnaissance et protection : inclure formellement les femmes dans le secteur minier, garantir leur sécurité et prévenir les violences.\n\nLutte contre l’impunité : sanctionner sévèrement les auteurs d’abus, d’escroqueries et de violences sexuelles.\n\nDéveloppement durable et inclusion : permettre aux femmes d’accéder à la formation, à la gestion et à l’entrepreneuriat minier pour briser le cycle de dépendance.\n\nLa RDC est assise sur l’un des plus grands trésors miniers du monde, mais ses citoyens et particulièrement ses femmes n’en récoltent que la souffrance.\n\nTant que la guerre, la corruption et le patriarcat dicteront leurs lois dans les mines, le pays restera riche de minerais mais pauvre d’humanité.', '/__l5e/assets-v1/a85ed393-1389-411d-bdef-93d1f57c64b1/WhatsApp-Image-2025-10-22-at-7.17.55-AM.jpeg', NULL, 'fe9719a8-01fe-4ec7-a344-f81db679f2d6', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2025-10-22 14:37:09', NULL, 3, 0, 0, 'RDC: Les femmes de la mine: les creuseuses sans bêche', 'Après une semaine dans différents carrés miniers au Sud-Kivu, Reelactu a rencontré des creseurs dont des femmes et leurs chefs pour comprendre ce qu’elles ', 0, 0, '2026-08-02 11:23:55', '2026-08-04 16:32:18'),
('a643c267-0964-40e1-85b1-a49378981eec', 'ebola-a-goma-la-menace-sanitaire-sintensifie-dans-une-ville-isolee-sous-controle-rebelle', 'Ebola à Goma: la menace sanitaire s’intensifie dans une ville isolée sous contrôle rebelle', 'La menace d’une propagation du virus Ebola dans la ville de Goma prend une dimension particulièrement alarmante après l’annonce d’un premier cas signalé dans cette ville stratégique du Nord-Kivu actuellement sous contrôle des rebelles du M23 soutenus par le Rwanda. Déjà…', 'La menace d’une propagation du virus Ebola dans la ville de Goma prend une dimension particulièrement alarmante après l’annonce d’un premier cas signalé dans cette ville stratégique du Nord-Kivu actuellement sous contrôle des rebelles du M23 soutenus par le Rwanda.\n\nDéjà fragilisée par des mois de conflit, de déplacements massifs de populations et de rupture des circuits sanitaires classiques et financiers avec la fermeture des banques, de l’aéroport international de Goma, la ville fait désormais face à une crise sanitaire potentiellement explosive dans un contexte d’isolement quasi total.\n\nQuelques heures après les alertes autour de ce cas suspect lié à la souche Bundibugyo, les autorités rwandaises ont procédé à la fermeture de leur frontière avec Goma, principal point de sortie et d’approvisionnement de la ville. Cette décision renforce les inquiétudes autour de l’accès aux soins, à l’aide humanitaire et aux intrants médicaux nécessaires à la riposte.\n\nDans les structures sanitaires locales, des professionnels de santé redoutent un scénario critique si des mesures logistiques urgentes ne sont pas prises pour éviter une rupture de la chaîne de prise en charge.\n\n« Sans corridor humanitaire et sans accès aérien opérationnel, la riposte risque d’être gravement compromise », confie une source médicale présente à Goma.\n\nDans ce contexte, plusieurs voix s’élèvent pour demander l’ouverture urgente de l’aéroport international de Goma afin de permettre l’acheminement du personnel qualifié, des équipements de protection, des laboratoires mobiles et des médicaments essentiels.\n\nLa situation est d’autant plus préoccupante qu’aucun vaccin ni traitement spécifique n’existe actuellement contre la souche Bundibugyo. Toutefois, l’Institut national de recherche biomédicale (INRB) appelle à éviter la panique. Le professeur Jean-Jacques Muyembe rappelle que la RDC a déjà réussi à maîtriser plusieurs flambées d’Ebola sans vaccin.\n\nSelon le ministre de la Santé Samuel Roger Kamba, plus de 350 cas suspects et 91 décès probables ont déjà été recensés en Ituri, principalement à Bunia et Mongwalu, épicentres actuels de l’épidémie.\n\nAlors que la peur gagne progressivement les habitants de Goma, les acteurs sanitaires craignent que l’enclavement de la ville ne transforme une crise épidémique localisée en urgence régionale majeure.\n\nTamende Glody', '/__l5e/assets-v1/4cf8d880-3611-47f3-bdbb-b7a7477636d9/IMG-20260518-WA0003.jpg', NULL, '483c6016-e901-488d-ba50-48aad757557c', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2026-05-18 06:34:16', NULL, 2, 0, 0, 'Ebola à Goma: la menace sanitaire s’intensifie dans une vill', 'La menace d’une propagation du virus Ebola dans la ville de Goma prend une dimension particulièrement alarmante après l’annonce d’un premier cas signalé da', 0, 0, '2026-08-02 11:23:55', '2026-08-04 16:32:18'),
('edfaa379-dbc8-41cd-b17d-9d38209b6935', 'ebola-en-ituri-roger-kamba-brise-le-silence-et-appelle-a-cesser-de-croire-aux-maladies-mystiques', 'Ebola en Ituri: Roger Kamba brise le silence et appelle à “cesser de croire aux maladies mystiques”', 'Le gouvernement congolais tente d’éviter le pire. Trois jours seulement après la confirmation officielle du diagnostic d’Maladie à virus Ebola, le ministre de la Santé, Roger Kamba, s’est rendu personnellement en Ituri pour superviser la riposte sanitaire et envoyer un message…', 'Le gouvernement congolais tente d’éviter le pire. Trois jours seulement après la confirmation officielle du diagnostic d’Maladie à virus Ebola, le ministre de la Santé, Roger Kamba, s’est rendu personnellement en Ituri pour superviser la riposte sanitaire et envoyer un message de fermeté à la population.\n\n« Ce n’est pas une maladie mystique », a martelé le ministre, dénonçant implicitement les croyances et les rumeurs qui freinent souvent la prise en charge rapide des malades lors des précédentes flambées épidémiques en République démocratique du Congo.\n\nFace à la presse et aux autorités locales, Roger Kamba a insisté sur l’urgence de collaborer avec les équipes médicales : « Faites-vous connaître pour qu’on vous prenne en charge et pour éviter que la maladie se généralise. »\n\nUne riposte déclenchée en urgence\n\nLe ministre a voulu démontrer la rapidité de la réaction gouvernementale. Selon lui, le diagnostic a été confirmé jeudi soir, avant une déclaration officielle le lendemain. Dès lors, des équipes médicales ont été déployées dans les zones touchées pour effectuer les prélèvements, organiser les enquêtes sanitaires et préparer les centres de traitement.\n\nTrois sites stratégiques ont déjà été identifiés à Rampara, Mongwalu et Bunia pour accueillir les structures de prise en charge. Des tentes médicales, du matériel d’urgence et des ressources humaines spécialisées ont été acheminés sur place afin de renforcer les capacités sanitaires locales déjà sous forte pression.\n\n59 malades hospitalisés, plus de 350 cas suspects\n\nLe bilan communiqué par le ministre révèle une situation préoccupante. À ce stade, 59 patients sont activement pris en charge dans les structures sanitaires, tandis qu’environ 350 cas suspects font l’objet d’investigations.\n\nAutre chiffre alarmant : 91 décès probables ont déjà été signalés. Toutefois, le ministre appelle à la prudence sur ce bilan, précisant que toutes les victimes ne sont pas encore officiellement confirmées comme étant liées à Ebola.\n\n« Avec les investigations, nous allons déterminer les causes exactes. Il pourrait y avoir moins de décès liés à Ebola que ce qui est actuellement rapporté », a-t-il expliqué.\n\n“Le traitement est gratuit”\n\nConscient de la peur et de la méfiance qui accompagnent souvent les épidémies, Roger Kamba a tenté de rassurer les populations : la prise en charge est entièrement gratuite et les soins seront renforcés dans les prochains jours.\n\nLe gouvernement affirme également maintenir une surveillance continue de la cartographie des risques afin d’adapter rapidement sa stratégie de riposte selon l’évolution de la situation.\n\nDaniel Michombero', '/__l5e/assets-v1/9c42cdf7-b069-415b-8c4e-8d747baeb928/20260518_042140.png', NULL, 'cc3b3143-d2ab-4b75-8add-e0a121fb1b1f', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2026-05-17 20:53:20', NULL, 2, 0, 0, 'Ebola en Ituri: Roger Kamba brise le silence et appelle à “c', 'Le gouvernement congolais tente d’éviter le pire. Trois jours seulement après la confirmation officielle du diagnostic d’Maladie à virus Ebola, le ministre', 0, 0, '2026-08-02 11:23:55', '2026-08-02 12:16:58'),
('c1b9a221-82b3-47a3-94ba-33105eb3e8dd', 'visa-americain-la-rdc-n-est-pas-concernee-par-la-caution-obligatoire-de-10-000-a', 'Visa américain : la RDC n’est pas concernée par la caution obligatoire de 10 000 à 20 000 dollars', 'Contrairement à des informations largement relayées ces derniers jours par plusieurs médias internationaux, la République démocratique du Congo (RDC) ne figure pas sur la liste officielle des pays dont les ressortissants peuvent être soumis à une caution de 10 000 à 20 000 dollars américains pour l’obtention d’un visa touristique ou d’affaires (B-1/B-2) des États-Unis.', 'Le Département d’État américain a rendu permanent, à compter du 3 août 2026, son programme de caution pour certaines demandes de visas. Cette mesure autorise les agents consulaires à exiger, au cas par cas, le versement d’une garantie financière comprise entre 10 000 et 20 000 dollars auprès des ressortissants de 50 pays, principalement africains, considérés comme présentant un risque élevé de dépassement de la durée de séjour autorisée. \n\nToutefois, la République démocratique du Congo ne figure pas sur la liste officielle publiée par le Département d’État américain. Cette liste comprend notamment la Côte d’Ivoire, le Sénégal, le Nigeria, l’Éthiopie, l’Ouganda et la Zambie, entre autres, mais pas la RDC. \n\nUne confusion relayée par plusieurs médias\n\nLa confusion est née après la publication d’articles par certains médias internationaux, dont RFI, AllAfrica et TV5 Monde, qui ont mentionné par erreur la RDC parmi les pays concernés, parfois en reprenant également le Ghana dans leurs listes. Or, cette affirmation ne correspond pas à la liste officielle diffusée par les autorités américaines. \n\nEn conséquence, les citoyens congolais continuent d’être soumis aux procédures habituelles pour les demandes de visas américains de type B-1/B-2, sans application automatique de cette caution financière.\n\nUne mesure destinée à lutter contre les dépassements de séjour\n\nSelon Washington, cette politique vise à réduire les cas de dépassement de la durée de validité des visas. Les agents consulaires disposent d’un pouvoir discrétionnaire pour imposer cette caution aux demandeurs issus des pays concernés. Si le voyageur respecte les conditions de son séjour et quitte les États-Unis dans les délais prévus, la somme versée est restituée. En revanche, elle peut être conservée par les autorités américaines en cas de non-respect des conditions du visa. \n\nCette réforme porte le plafond de la caution de 15 000 à 20 000 dollars, tandis que le montant minimum passe de 5 000 à 10 000 dollars, renforçant ainsi le dispositif mis en place à titre pilote en 2025. \n\nLa précision\n\nÀ ce jour, aucune disposition officielle n’impose cette caution aux ressortissants de la République démocratique du Congo. Toute information affirmant le contraire ne reflète pas la liste officielle publiée par le Département d’État des États-Unis. \n', '/api/public/media/2026/f176954b-6431-40c9-8817-b5868b3bc85c.webp', 'Un demandeur de visa devant un guichet consulaire de l’ambassade des États-Unis, illustrant les nouvelles règles américaines en matière de visas. Droits tiers', '65df35f4-289f-4a06-8b4d-8e3c510c68d3', 'c4024581-a8d4-4a10-8657-43ec2b68431f', 'd0cf6ad7-a1a2-4871-871c-44b12548eea8', 'publie', '2026-08-04 15:44:58', 'Etas-Unis', 3, 1, 0, '', '', 0, 0, '2026-08-04 15:44:58', '2026-08-04 16:32:18'),
('3b2a5649-878c-4f07-9f42-b6846efeab02', 'journee-mondiale-de-la-liberte-de-la-presse-dune-voix-de-bukavu-a-la-communication-humanitaire-le-parcours-dyves-ndjadi-lopongo', 'Journée mondiale de la liberté de la presse: d’une voix de Bukavu à la communication humanitaire, le parcours d’Yves Ndjadi Lopongo', 'À l’occasion de la Journée mondiale de la liberté de la presse, célébrée chaque mois de mai, notre rédaction consacre un portrait aux trajectoires de journalistes congolais dont les voix ont marqué l’espace médiatique avant de s’inscrire dans d’autres domaines de la…', 'À l’occasion de la Journée mondiale de la liberté de la presse, célébrée chaque mois de mai, notre rédaction consacre un portrait aux trajectoires de journalistes congolais dont les voix ont marqué l’espace médiatique avant de s’inscrire dans d’autres domaines de la communication. Parmi eux, Yves Ndjadi Lopongo, ancien journaliste de Bukavu devenu professionnel de la communication humanitaire internationale.\n\nVoix familière des auditeurs de la radio, Yves Ndjadi Lopongo a d’abord exercé comme journaliste à Bukavu, où il a contribué à la production de contenus sociaux et politiques. Il est notamment passé par plusieurs rédactions locales, occupant des fonctions de rédaction et de présentation d’émissions d’information et de débats.\n\nIl a également été correspondant de la radio Top Congo FM à Bukavu, où sa voix accompagnait des reportages ancrés dans les réalités sociales et politiques de l’est de la République démocratique du Congo. Ces contenus, diffusés à l’échelle nationale, abordaient des thématiques de gouvernance, de société et de vie quotidienne dans une région souvent au cœur de l’actualité.\n\n« C’était une période où le journalisme de terrain avait un impact direct. Les auditeurs attendaient des récits proches de leur vécu », confie-t-il en revenant sur ses années dans les médias.\n\nDans ce paysage médiatique, il participe également à des émissions de débats et de société au sein de médias locaux, contribuant à faire émerger des espaces de discussion publique dans un contexte souvent tendu.\n\nProgressivement, son parcours s’ouvre à des collaborations avec des structures engagées dans le développement des médias et la formation journalistique. Il travaille notamment avec des organisations impliquées dans la production de contenus médiatiques et l’accompagnement de jeunes journalistes, où il commence à occuper un rôle de formateur.\n\nC’est à l’École technique de journalisme de Bukavu qu’il s’investit particulièrement dans la transmission de son expérience. Plusieurs anciens étudiants évoquent aujourd’hui son rôle dans leur parcours professionnel. Parmi eux, le journaliste Hugor Tamwe, qui souligne son influence dans leur apprentissage du journalisme de terrain et de la rigueur professionnelle.\n\n« Il insistait sur la responsabilité du journaliste face à l’information, surtout dans les contextes sensibles », rapporte-t-il.\n\nAu fil des années, Yves Ndjadi Lopongo s’oriente vers la communication en contexte de crise, un domaine qu’il découvre à travers les réalités humanitaires de l’est de la RDC. Il participe alors à la gestion de la communication dans des situations d’urgence, où l’information devient un outil essentiel de coordination et de sensibilisation.\n\n« En situation de crise, la communication ne consiste pas seulement à informer, mais aussi à éviter la confusion et à renforcer la confiance », explique-t-il dans plusieurs interventions médiatiques consacrées aux enjeux humanitaires.\n\nCe parcours le conduit ensuite à évoluer hors de son pays. Après plusieurs années en République démocratique du Congo, il travaille dans différents contextes internationaux, notamment au Soudan et en France, avant de s’installer au Tchad, où il occupe aujourd’hui des fonctions de responsabilité dans le département de la communication d’une organisation humanitaire internationale. Il y pilote la stratégie de communication et la coordination des messages dans des contextes marqués par des crises sanitaires et des déplacements de populations.\n\nDans ce rôle, il insiste sur l’adaptation des messages aux réalités locales : « Une communication efficace est celle qui comprend le terrain et les personnes à qui elle s’adresse. »\n\nAuteur de l’ouvrage Les Masques du destin : entre pouvoir et manipulation, il poursuit également une réflexion sur les relations entre information, société et pouvoir.\n\nCe portrait, réalisé à l’occasion de la Journée mondiale de la liberté de la presse, s’inscrit dans une série consacrée à ces trajectoires de journalistes devenus communicants, ces voix autrefois entendues à la radio et ces visages familiers de l’information télévisée, aujourd’hui engagés autrement dans l’espace public et l’action humanitaire.', '/__l5e/assets-v1/552c9efb-b108-4d8e-a3d3-b2f0aaf916f5/IMG-20260626-WA0019-1.jpg', NULL, '83a1c6b5-fb20-4b26-9cdd-9c5370cd95c2', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2026-06-26 18:42:44', NULL, 3, 1, 0, 'Journée mondiale de la liberté de la presse: d’une voix de B', 'À l’occasion de la Journée mondiale de la liberté de la presse, célébrée chaque mois de mai, notre rédaction consacre un portrait aux trajectoires de journ', 0, 0, '2026-08-02 11:23:55', '2026-08-04 16:32:18'),
('bf35a2ca-bf54-446c-b041-0f7fa7b5e0e3', 'ebola-bundibugyo-loms-declenche-une-urgence-sanitaire-internationale', '#Ebola Bundibugyo: l’OMS déclenche une urgence sanitaire internationale', 'L’Organisation mondiale de la santé a déclaré, samedi 16 mai, que l’épidémie de maladie à virus Ebola de souche Bundibugyo qui touche la République démocratique du Congo et l’Ouganda constitue désormais une « urgence de santé publique de portée internationale » (USPPI).…', 'L’Organisation mondiale de la santé a déclaré, samedi 16 mai, que l’épidémie de maladie à virus Ebola de souche Bundibugyo qui touche la République démocratique du Congo et l’Ouganda constitue désormais une « urgence de santé publique de portée internationale » (USPPI). L’organisation précise toutefois que la situation ne répond pas, à ce stade, aux critères d’une urgence pandémique.\n\nSelon les données communiquées par l’OMS, le bilan provisoire fait état de 8 cas confirmés en laboratoire, 246 cas suspects et 80 décès signalés dans la province de l’Ituri, principalement dans les zones de santé de Bunia, Rwampara et Mongbwalu. Deux cas confirmés, dont un décès, ont également été recensés à Kampala, tandis qu’un autre cas a été détecté à Kinshasa chez une personne revenant d’Ituri.\n\nL’OMS justifie cette décision par plusieurs facteurs préoccupants, notamment l’absence de vaccin et de traitement homologués contre la souche Bundibugyo, le taux élevé de positivité observé sur les premiers échantillons analysés ainsi que les risques accrus de propagation liés à l’insécurité persistante, aux déplacements massifs de populations et à la forte mobilité urbaine dans les zones touchées.\n\n@WHO a par ailleurs exhorté les États à éviter toute fermeture des frontières ou interruption des échanges commerciaux, estimant que de telles mesures « n’ont aucune base scientifique » et pourraient compliquer davantage le contrôle sanitaire en favorisant des passages informels non surveillés.', '/__l5e/assets-v1/32f99bad-3087-4617-b4ae-2ccb2721759a/IMG-20260517-WA0000.jpg', NULL, '483c6016-e901-488d-ba50-48aad757557c', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2026-05-17 06:20:45', NULL, 1, 0, 0, '#Ebola Bundibugyo: l’OMS déclenche une urgence sanitaire int', 'L’Organisation mondiale de la santé a déclaré, samedi 16 mai, que l’épidémie de maladie à virus Ebola de souche Bundibugyo qui touche la République démocra', 0, 0, '2026-08-02 11:23:55', '2026-08-02 15:44:30'),
('c5db1ec3-49ab-4057-9c63-b379c3de734a', 'ebola-en-ituri-comprendre-les-pratiques-funeraires-pour-eviter-les-resistances-communautaires', 'Ebola en Ituri: comprendre les pratiques funéraires pour éviter les résistances communautaires', 'Alors que la riposte contre l’épidémie d’Ebola se poursuit en Ituri, des chercheurs et spécialistes réunis au sein du « Collectif pour l’Ituri » appellent les autorités sanitaires et les partenaires de santé à placer les communautés au cœur de la réponse. Dans une note…', 'Alors que la riposte contre l’épidémie d’Ebola se poursuit en Ituri, des chercheurs et spécialistes réunis au sein du « Collectif pour l’Ituri » appellent les autorités sanitaires et les partenaires de santé à placer les communautés au cœur de la réponse. Dans une note contextuelle publiée le 2 juin 2026, ils soulignent que la compréhension des pratiques funéraires locales constitue un élément déterminant pour limiter la propagation du virus tout en évitant les tensions avec les populations.\n\nLes funérailles, un enjeu sanitaire majeur\n\nLa maladie à virus Ebola se transmet notamment par contact direct avec les personnes malades ou avec les corps des personnes décédées. Les rites funéraires traditionnels, qui impliquent souvent la toilette mortuaire, l’habillage du défunt, les derniers hommages et parfois le contact physique avec le corps, représentent donc un moment particulièrement sensible dans la chaîne de transmission.\n\nLes chercheurs insistent cependant sur un point souvent mal compris : la simple présence à des funérailles ne constitue pas en elle-même un risque élevé. Ce sont surtout certains gestes précis, notamment la manipulation du corps et l’exposition aux fluides corporels, qui présentent un danger.\n\nLes femmes figurent parmi les personnes les plus exposées, en raison de leur rôle central dans les soins apportés aux malades et dans la préparation des défunts avant l’enterrement.\n\nAssocier les familles plutôt que les exclure\n\nL’une des principales recommandations de la note consiste à éviter une approche autoritaire ou exclusivement sécuritaire des enterrements.\n\nSelon les auteurs, les familles ne doivent pas être considérées comme un obstacle à la riposte, mais comme des partenaires indispensables. Lorsque les proches sont tenus à l’écart des décisions ou empêchés de voir le corps du défunt, la méfiance s’installe rapidement.\n\nDans plusieurs communautés de l’Ituri, l’impossibilité de voir le corps peut alimenter des rumeurs de prélèvements d’organes, de disparition du défunt ou d’autres pratiques supposées occultes. Ces suspicions s’inscrivent dans un contexte historique marqué par la défiance envers les institutions et les interventions extérieures.\n\nLes experts recommandent ainsi de permettre, lorsque les conditions de sécurité le permettent, une inspection visuelle du corps par certains membres de la famille, sans contact physique, afin de garantir la transparence du processus.\n\nPrendre en compte la dimension sociale des funérailles\n\nEn Ituri, les funérailles dépassent largement le cadre religieux ou familial. Elles constituent un événement social majeur où se règlent parfois des questions de succession, de dot, d’héritage ou de conflits familiaux anciens.\n\nUn enterrement peut ainsi être retardé ou perturbé par des différends qui n’ont aucun lien avec Ebola. Dans certains cas, les équipes de la riposte risquent d’être prises à partie alors que les tensions trouvent en réalité leur origine dans des litiges préexistants.\n\nLes auteurs recommandent donc d’identifier à l’avance les situations potentiellement conflictuelles et de dialoguer avec les personnes reconnues comme autorités familiales ou coutumières.\n\nLe défi du transport des corps\n\nLa note attire également l’attention sur une pratique profondément ancrée dans les habitudes locales : le rapatriement des dépouilles vers le village d’origine.\n\nDe nombreuses familles considèrent comme essentiel que leurs proches soient enterrés sur la terre ancestrale, même lorsque cela implique un long déplacement. En période d’épidémie, ces transports sont interdits en raison du risque sanitaire. Toutefois, les chercheurs estiment que leur importance symbolique pourrait favoriser leur poursuite dans la clandestinité.\n\nCette réalité doit être anticipée par les équipes de terrain afin d’éviter des confrontations inutiles avec les communautés.\n\nMiser sur les leaders religieux et coutumiers\n\nLes auteurs soulignent le rôle crucial que peuvent jouer les chefs coutumiers, les responsables religieux et les notables locaux dans l’acceptation des mesures sanitaires.\n\nLorsque les messages de prévention sont relayés par des figures de confiance issues de la communauté, ils sont généralement mieux compris et davantage respectés que lorsqu’ils apparaissent comme des injonctions venues de l’extérieur.\n\nLa sensibilisation par les radios locales, les églises, les mosquées et les leaders d’opinion est ainsi présentée comme un levier essentiel pour réduire les résistances.\n\nHumaniser la riposte\n\nAu-delà des aspects techniques, la note appelle à une riposte plus humaine. Les chercheurs recommandent aux équipes chargées des enterrements dignes et sécurisés de prendre le temps d’écouter les familles, de leur présenter des condoléances et de les associer aux décisions concernant les vêtements du défunt, le lieu de sépulture ou le déroulement de la cérémonie.\n\nSelon eux, la rapidité imposée par les impératifs sanitaires ne doit pas être perçue comme un manque de respect envers les morts et leurs proches.\n\n« Plus les familles sont associées au processus, moins elles vivent l’enterrement comme une dépossession », résument les auteurs.\n\nUne leçon des précédentes épidémies\n\nL’expérience des précédentes flambées d’Ebola en Afrique montre que les réponses sanitaires les plus efficaces sont celles qui s’appuient sur les savoirs locaux plutôt que celles qui cherchent à les contourner.\n\nPour les chercheurs du Collectif pour l’Ituri, la lutte contre Ebola ne repose pas uniquement sur les mesures médicales. Elle dépend aussi de la capacité des autorités sanitaires à comprendre les réalités sociales, culturelles et familiales qui entourent la maladie et la mort.\n\nDans un contexte marqué par la méfiance et la circulation des rumeurs, le dialogue, la transparence et le respect des communautés apparaissent ainsi comme des outils aussi essentiels que les mesures de biosécurité elles-mêmes.', '/__l5e/assets-v1/6af89df9-6eb2-4a17-9be5-dfdbc65781fe/IMG-20260602-WA0103.jpg', NULL, '483c6016-e901-488d-ba50-48aad757557c', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2026-06-02 20:05:06', NULL, 4, 0, 0, 'Ebola en Ituri: comprendre les pratiques funéraires pour évi', 'Alors que la riposte contre l’épidémie d’Ebola se poursuit en Ituri, des chercheurs et spécialistes réunis au sein du « Collectif pour l’Ituri » appellent ', 0, 0, '2026-08-02 11:23:55', '2026-08-02 15:44:30'),
('82279aeb-fa79-4211-8435-0b55b8b56844', 'ebola-en-rdc-lituri-demeure-lepicentre-avec-plus-de-320-cas-confirmes', 'Ebola en RDC: l’Ituri demeure l’épicentre avec plus de 320 cas confirmés', 'L’épidémie de la maladie à virus Ebola demeure active dans l’est de la République démocratique du Congo, avec un total cumulé de 321 cas confirmés enregistrés au 31 mai 2026, selon le dernier rapport de situation publié le 1er juin par les autorités sanitaires. Les données…', 'L’épidémie de la maladie à virus Ebola demeure active dans l’est de la République démocratique du Congo, avec un total cumulé de 321 cas confirmés enregistrés au 31 mai 2026, selon le dernier rapport de situation publié le 1er juin par les autorités sanitaires.\n\nLes données épidémiologiques font également état de 48 décès parmi les cas confirmés, tandis que 238 patients sont actuellement pris en charge. Au cours de la journée du 31 mai, six nouvelles guérisons ont été enregistrées et 12 nouveaux cas confirmés ont été notifiés.\n\nTrois provinces sont touchées par l’épidémie : l’Ituri, le Nord-Kivu et le Sud-Kivu. L’Ituri reste la province la plus affectée, avec 15 zones de santé concernées sur les 36 que compte la province. La zone de santé de Logo figure désormais parmi les nouvelles zones touchées, portant à 23 le nombre total de zones de santé affectées dans les trois provinces.\n\nLes autorités sanitaires soulignent que la maladie continue de représenter une menace de propagation. Au total, 116 cas suspects sont encore en cours d’investigation et 104 personnes demeurent en isolement. Le taux de suivi des contacts reste limité à 43 %, un indicateur jugé préoccupant pour le contrôle de la transmission.\n\nSur le terrain, plusieurs avancées ont néanmoins été enregistrées. Quatre patients guéris ont quitté le Centre médical évangélique de Bunia, tandis que le Centre de traitement Ebola de Rwampara a été officiellement inauguré afin de renforcer la capacité de prise en charge. Les équipes de riposte ont également reçu 162 poches de sang destinées aux soins transfusionnels ainsi que 30 motos fournies par le gouvernement central pour améliorer la surveillance et la coordination des interventions.\n\nLes autorités sanitaires appellent les communautés à renforcer leur collaboration avec les équipes de riposte. Elles déplorent la persistance de résistances communautaires à Bunia et à Nizi ainsi que la circulation de rumeurs qui compliquent les opérations de surveillance et la prise en charge des malades.\n\nMalgré une situation sécuritaire relativement calme à Bunia et à Rwampara, l’insécurité continue de limiter l’accès humanitaire dans plusieurs zones affectées, compliquant davantage les efforts de lutte contre l’épidémie.', '/__l5e/assets-v1/31759ca2-afa3-48dc-a322-10c392925b39/IMG-20260602-WA0003.jpg', NULL, '483c6016-e901-488d-ba50-48aad757557c', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2026-06-02 05:28:14', NULL, 2, 0, 0, 'Ebola en RDC: l’Ituri demeure l’épicentre avec plus de 320 c', 'L’épidémie de la maladie à virus Ebola demeure active dans l’est de la République démocratique du Congo, avec un total cumulé de 321 cas confirmés enregist', 0, 0, '2026-08-02 11:23:55', '2026-08-02 15:44:30'),
('80cfcd2c-4a03-4d1e-82c5-4e7c666ccfb0', 'rutshuru-un-jeune-de-24-ans-tue-a-kabaya-par-les-rebelles-du-m23', 'Rutshuru: Un jeune de 24 ans tué à Kabaya par les rebelles du M23.', 'Un jeune nommé Hatangimana Ntuyenabo âgé de 24 ans à été tué par balle ce samedi 23 mai 2026 à 20h dans la localité de Kabaya, groupement de Kisigari en Territoire de Rutshuru. Selon nos sources, ce jeune originaire de ce village revenait il ya une', 'Un jeune nommé Hatangimana Ntuyenabo\n\nâgé de 24 ans à été tué par balle ce samedi 23 mai 2026 à 20h dans la localité de Kabaya, groupement de Kisigari en Territoire de Rutshuru.\n\nSelon nos sources, ce jeune originaire de ce village revenait il ya une semaine de Kampala en ouganda où il sejournait depuis plusieurs années pour des raisons d’occupations.\n\nAu soir de ce samedi, ce jeune qui prenait une bouteille dans un bistron de la place a été abbatu par des hommes en armes en tenue militaire assimilés aux combatants du M23 qui occueant cette zone.\n\n« des militaires ont fait incursion dans une buvette et ont abbatu un jeune qu’ils ont suspecté d’etre non résident de notre l’entité, ils l’ont tiré des balles sans demander plus d’explications » a révelé un leader communautaire de kabaya et ayant recquis l’anonymat pour des raisons de securité.\n\nLa victime en état critique a eté acheminée au centre de santé de Kabaya où il a sucombé de ses blesures quelques heures après.\n\nSa famille aurait tentée d’avoir des explications sur les circonstances de sa mort ainsi que les auteurs de cet assassinat mais en vain, a conclu notre source.\n\nJustin Bizimana', '/__l5e/assets-v1/c705b406-3c08-4799-b7cf-bc777d233f99/IMG-20260525-WA0006.jpg', NULL, '578a4dc1-5069-4500-b734-d675df9be940', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2026-05-25 11:01:22', NULL, 1, 0, 0, 'Rutshuru: Un jeune de 24 ans tué à Kabaya par les rebelles d', 'Un jeune nommé Hatangimana Ntuyenabo âgé de 24 ans à été tué par balle ce samedi 23 mai 2026 à 20h dans la localité de Kabaya, groupement de Kisigari en Te', 0, 0, '2026-08-02 11:23:55', '2026-08-02 12:16:58'),
('e463f4cb-df6e-4aa1-ad67-8671da7b9656', 'les-fardc-nont-pas-cible-la-communaute-banyamulenge-a-uvira', 'Les FARDC n’ont pas ciblé la communauté Banyamulenge à Uvira', 'Dans un article publié le 20 janvier 2026, le site Kivu Morning Post affirme que les Forces armées de la République démocratique du Congo (FARDC) auraient mené des « violences ciblées » contre la communauté Banyamulenge à Uvira, après le retrait des rebelles du M23 le 17…', 'Dans un article publié le 20 janvier 2026, le site Kivu Morning Post affirme que les Forces armées de la République démocratique du Congo (FARDC) auraient mené des « violences ciblées » contre la communauté Banyamulenge à Uvira, après le retrait des rebelles du M23 le 17 janvier.\n\nCe que nous avons vérifié :\n\nCette accusation repose notamment sur une photographie censée illustrer des exactions commises à Uvira. Or, après vérification, cette image a été publiée pour la première fois le 7 janvier 2020 et provient de Fizi, dans le Sud-Kivu. Elle est donc antérieure de plusieurs années aux événements évoqués et ne peut en aucun cas prouver des faits survenus en janvier 2026 à Uvira.\n\nhttps://congocheck.net/cette-photo-prise-a-fizi-en-2020-na-aucun-lien-avec-les-elements-m23-arretes-a-rutshuru/\n\nL’utilisation d’une image sortie de son contexte constitue une manipulation visuelle, fréquemment observée dans les campagnes de désinformation liées au conflit dans l’Est de la RDC. Présenter une photo ancienne comme preuve d’événements récents fausse la compréhension du public et jette un doute sérieux sur la crédibilité de l’allégation.\n\nCe que disent les sources locales :\n\nÀ l’inverse, plusieurs médias locaux indépendants rapportent que les FARDC ont déployé des dispositifs de protection à Uvira, y compris en faveur des familles Banyamulenge qui ont refusé d’être instrumentalisées par les rebelles du M23.\n\nSelon ces sources, l’armée congolaise sécurise les quartiers sensibles et accompagne les communautés dans une reprise progressive de la vie normale.\n\nDes reportages publiés le même jour indiquent que des familles Banyamulenge ont été présentées publiquement par les FARDC dans un cadre sécurisé, attestant qu’elles se trouvaient sous protection et non sous menace.\n\nhttps://jicholakivu.com/index.php/2026/01/20/sud-kivu-sous-protection-des-fardc-les-communautes-renouent-avec-la-vie-a-uvira/\n\nAutre élément clé :\n\nPlusieurs familles Banyamulenge, y compris issues de la diaspora, ont dénoncé la déportation de certains membres de leur communauté vers le Rwanda à des fins politiques. Ces témoignages contredisent la thèse d’une persécution systématique par les forces congolaises et renforcent l’idée d’une instrumentalisation communautaire dans la communication des groupes armés et de leurs relais médiatiques.\n\nhttps://x.com/michombero/status/2012845678599279051?s=46\n\nConclusion : Faux / Trompeur\n\nAucune preuve indépendante ne confirme que les FARDC aient mené des violences ciblées contre la communauté Banyamulenge à Uvira en janvier 2026.\n\nL’article de Kivu Morning Post s’appuie sur une image ancienne, sans lien avec les faits allégués, et omet les informations concordantes issues des médias locaux faisant état d’une protection des familles Banyamulenge par les FARDC.\n\nCette publication est donc trompeuse et s’inscrit dans une narration déjà observée dans l’espace numérique, visant à justifier la présence du M23 et de ses soutiens en présentant l’État congolais comme persécuteur d’une communauté spécifique, sans fondement factuel vérifié.\n\nDaniel Michombero', '/__l5e/assets-v1/9a92f568-80cb-4ace-a036-fa2a38866262/20260120_184742.jpg', NULL, '65df35f4-289f-4a06-8b4d-8e3c510c68d3', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2026-01-20 16:52:12', NULL, 2, 0, 0, 'Les FARDC n’ont pas ciblé la communauté Banyamulenge à Uvira', 'Dans un article publié le 20 janvier 2026, le site Kivu Morning Post affirme que les Forces armées de la République démocratique du Congo (FARDC) auraient ', 0, 0, '2026-08-02 11:23:55', '2026-08-04 16:32:18'),
('c75043a1-fff1-4365-a0ae-ff8f83d82098', 'rdc-a-uvira-la-cohabitation-pacifique-au-coeur-de-la-strategie-de-felix-tshisekedi', 'RDC: à Uvira, la cohabitation pacifique au cœur de la stratégie de Félix Tshisekedi', 'Depuis son accession à la magistrature suprême, la cohabitation pacifique entre communautés s’est imposée comme l’un des piliers de la politique du président Félix Tshisekedi pour la stabilisation durable du pays en général, et de l’Est de la République démocratique du Congo en…', 'Depuis son accession à la magistrature suprême, la cohabitation pacifique entre communautés s’est imposée comme l’un des piliers de la politique du président Félix Tshisekedi pour la stabilisation durable du pays en général, et de l’Est de la République démocratique du Congo en particulier. Convaincu que la paix sociale constitue un levier essentiel du développement national, le chef de l’État a choisi de traduire cette vision en actions concrètes sur le terrain.\n\nC’est dans ce cadre qu’une délégation composée 2 collaborateurs très proches du chef de l’État en matière de sécurité et un chargé de mission du chef de l’État en charge des questions communautaires et identitaires dans la partie orientale de la RDC a été dépêchée dans l’Est du pays. Pendant trois jours consécutifs, cette équipe a mené une série de rencontres afin de s’assurer de la mise en œuvre effective des mesures gouvernementales, notamment dans les secteurs de la défense et de la sécurité, du respect du droit international humanitaire (DIH) et de la cohabitation pacifique entre les communautés. Devant les militaires déployés au front, la délégation a mis l’accent sur le renforcement du moral des troupes. Elle a rappelé l’importance de la discipline, du respect de l’éthique militaire et du rejet de toute forme de tribalisme, d’exclusion fondée sur l’appartenance ethnique ou l’origine linguistique. La délégation a également insisté sur le comportement attendu des militaires et sur la mission fondamentale de l’armée, qui consiste à défendre l’intégrité territoriale et à protéger les populations civiles.\n\n« Sachez que vos efforts consentis depuis le début de cette guerre jusqu’à aujourd’hui sont considérés par le Président de la République, qui vous félicite et vous encourage à défendre la nation jusqu’au sacrifice suprême. Il nous a envoyés pour vous témoigner sa considération envers chacun d’entre vous. Sentez-vous à l’aise de nous partager vos besoins, ils seront traités avec intérêt », a déclaré l’un des collaborateurs du Président.\n\nLors des échanges avec l’ensemble des communautés, la délégation a réaffirmé la nécessité du vivre-ensemble, appelant à la lutte contre les discours de haine ethnique et toute forme d’exclusion sociale, considérés comme des facteurs majeurs d’instabilité et de division.\n\n« Le Président de la République nous a demandé de venir vous parler de l’unité et de la cohésion sociale des communautés. C’est ça, son message », a déclaré Jacques Kongolo, Chargé de mission du Président de la République en charge des questions communautaires et identitaires dans la partie orientale du pays. Il a mis en garde contre toute instrumentalisation identitaire, appelant les populations à ne pas relayer des messages de division.\n\nIl a par ailleurs assuré que des mesures ont été prises contre les acteurs politiques, militaires ou civils qui attisent la haine, promettant des sanctions à l’encontre de tous ceux qui alimentent les tensions communautaires.\n\nSur le terrain, plusieurs témoignages recueillis indiquent que la volonté de préserver la cohabitation pacifique reste bien ancrée au sein de la population d’Uvira, malgré le narratif rwandais visant à diviser les communautés qui ont vécu ensemble depuis des années.\n\nMulala Sandra, habitante de la ville, évoque une coexistence ancienne et fondée sur la confiance entre les communautés, notamment avec les Banyamulenge. Elle reconnaît toutefois que les manipulations existent dans toutes les communautés, appelant à une prise de conscience collective pour éviter toute stigmatisation.\n\nDu côté de la communauté Banyamulenge restée à Uvira, le discours met en avant à la fois la vigilance et l’espoir. Isaac Nduwayo, résident de la ville, salue la présence des Forces armées de la RDC (FARDC) et les assurances données par les autorités en matière de sécurité. Il souligne également le rôle déterminant de la solidarité locale, notamment l’engagement de voisins issus d’autres communautés qui ont contribué à la protection des familles restées sur place.\n\nCommerçants, leaders communautaires et responsables associatifs convergent sur la nécessité de rejeter toute forme de discours haineux. Pour Éric Nyindu, commerçant à Uvira, la diversité communautaire constitue une richesse qui doit être préservée dans un esprit de vivre-ensemble.\n\nMême son de cloche du côté du Barza intercommunautaire d’Uvira. Son président, Ngule Mukonda Delphin, affirme que la lutte contre les messages de haine demeure une priorité, estimant que ces discours constituent la principale source des conflits récurrents dans la région.\n\nLes autorités provinciales préparent désormais l’étape suivante. Le gouverneur du Sud-Kivu, Jean-Jacques Purusi, a annoncé des concertations avec les agences spécialisées des Nations unies afin d’organiser le retour des déplacés et des réfugiés. Ce processus, a-t-il précisé, devra se faire sur la base d’un screening rigoureux, garantissant la sécurité des populations et la stabilité des zones de retour.\n\nÀ l’issue de cette mission présidentielle, un constat s’impose : à Uvira, le message de la cohabitation pacifique semble avoir été largement compris. Reste désormais à le traduire en actions durables, dans un environnement sécuritaire. Pour les autorités congolaises, la ville pourrait ainsi devenir un laboratoire de la paix sociale voulue par le président Félix Tshisekedi dans l’Est de la RDC.\n\nDaniel Michombero', '/__l5e/assets-v1/54fa914c-0cdd-470d-a330-93d1eb44cdd3/IMG-20260126-WA0002-copie.jpg', NULL, 'a09b5ee2-27ae-4ddb-b057-04d88321d28e', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2026-01-26 07:21:33', NULL, 4, 0, 0, 'RDC: à Uvira, la cohabitation pacifique au cœur de la straté', 'Depuis son accession à la magistrature suprême, la cohabitation pacifique entre communautés s’est imposée comme l’un des piliers de la politique du préside', 0, 0, '2026-08-02 11:23:55', '2026-08-04 16:32:18'),
('edd40ce0-831e-4d46-9980-c2e881787f18', 'uvira-fardc-et-societe-civile-unissent-leurs-voix-pour-la-paix-et-la-cohesion-entre-communautes', 'Uvira: FARDC et société civile unissent leurs voix pour la paix et la cohésion entre communautés', 'Dans un contexte marqué par les tensions sécuritaires et les fractures communautaires dans les hauts et moyens plateaux du Sud-Kivu, un message fort en faveur de la paix et de la cohabitation pacifique vient d’être lancé à Uvira par les autorités militaires et les acteurs de la…', 'Dans un contexte marqué par les tensions sécuritaires et les fractures communautaires dans les hauts et moyens plateaux du Sud-Kivu, un message fort en faveur de la paix et de la cohabitation pacifique vient d’être lancé à Uvira par les autorités militaires et les acteurs de la société civile.\n\nEn déplacement à Luvungi après le retrait des groupes armés présents dans la zone, le commandant de la 33ᵉ région militaire, le général de brigade Dunia Kashindi Fabien, a appelé les populations à tourner définitivement la page des divisions ethniques et des violences communautaires.\n\n« Le grand message de ce jour est l’union de tous sans faire allusion aux communautés Fuliro, Bembe, Banyamulenge, Mubangubangu… c’est fini cette histoire », a déclaré l’officier supérieur devant la population.\n\nLe général Dunia a insisté sur le retour de l’autorité de l’État et la nécessité de restaurer un climat de sécurité permettant aux habitants de reprendre leurs activités normales.\n\n« Je ne veux pas entendre un seul coup de balle dans ce village. Tout celui qui ose faire ça sera arrêté. Il est temps que tout celui qui veut cultiver le fasse et que vous puissiez faire vos activités commerciales pour le développement de votre milieu », a-t-il averti.\n\nDans le même élan, l’armée congolaise annonce la suppression des barrières sur l’axe menant jusqu’à Uvira afin de réduire les tracasseries et de faciliter la libre circulation des personnes et des biens.\n\n« Désormais toutes les barrières jusqu’à Uvira sont supprimées, vous devez vous sentir à l’aise dans votre pays sans tracasseries », a affirmé le commandant de la 33ᵉ région militaire.\n\nLe message de l’armée rejoint celui porté par les acteurs de la société civile locale, qui appellent eux aussi à combattre les discours de haine et les manipulations identitaires.\n\nDepuis la cité de Sange, le coordinateur de la Dynamique de la société civile pour le développement durable, Mapenzi Manyebwa, a exhorté toutes les communautés du territoire d’Uvira à privilégier la cohésion sociale et le vivre-ensemble.\n\n« Nous avons besoin aujourd’hui de la paix et nous devons tous travailler pour combattre ces messages de haine, combattre ces informations qui viennent pour nous diviser », a-t-il déclaré.\n\nDans une adresse particulièrement forte, il a cité plusieurs communautés du territoire pour rappeler que l’avenir d’Uvira dépend désormais de leur capacité à vivre ensemble.\n\n« Que les Bavira, les Bafuliru, les Babembe, les Nyamulenge, les Bashis, les Barundi, les Bahavu et toutes les communautés dans leur diversité, nous ayons tous un esprit de cohésion sociale et que nous bannissions l’esprit de haine », a plaidé cet acteur de la société civile.\n\nPour lui, les divisions communautaires constituent aujourd’hui l’un des principaux obstacles à la stabilité et au développement de la région.\n\n« Nous ne devons plus donner la place à ces politiciens en mal de positionnement qui cherchent à créer des divisions entre les différentes tribus dans le territoire d’Uvira », a-t-il martelé.\n\nAlors que plusieurs localités du territoire d’Uvira tentent progressivement de retrouver une vie normale après des mois d’insécurité, ces appels convergents de l’armée et de la société civile apparaissent comme une volonté commune de reconstruire la confiance entre les communautés et de consolider la paix durable dans cette partie du Sud-Kivu.\n\nDanielMichombero', '/__l5e/assets-v1/f2721f4a-cd2b-4755-b924-9284e4cfc736/20260514_110158-1.jpg', NULL, '578a4dc1-5069-4500-b734-d675df9be940', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2026-05-14 09:35:27', NULL, 3, 0, 0, 'Uvira: FARDC et société civile unissent leurs voix pour la p', 'Dans un contexte marqué par les tensions sécuritaires et les fractures communautaires dans les hauts et moyens plateaux du Sud-Kivu, un message fort en fav', 0, 0, '2026-08-02 11:23:55', '2026-08-02 12:16:58'),
('08f4ee59-01ee-4f57-8f63-9afcb901469d', 'rdc-violents-affrontements-a-kalehe-lumbishi-replonge-dans-lincertitude', '#RDC | Violents affrontements à Kalehe: Lumbishi replonge dans l’incertitude', 'Une nouvelle flambée de violences secoue le territoire de Kalehe, dans la province du Sud-Kivu. Depuis l’aube du mardi 5 mai 2026, des combats d’une intensité inhabituelle opposent les groupes d’autodéfense dits « Wazalendo » aux rebelles de l’AFC-M23 dans les localités de…', 'Une nouvelle flambée de violences secoue le territoire de Kalehe, dans la province du Sud-Kivu. Depuis l’aube du mardi 5 mai 2026, des combats d’une intensité inhabituelle opposent les groupes d’autodéfense dits « Wazalendo » aux rebelles de l’AFC-M23 dans les localités de Lumbishi et Katale.\n\nSelon plusieurs témoignages recueillis sur place ainsi que des sources sécuritaires, des tirs d’armes lourdes et légères ont été entendus dès les premières heures de la matinée. À Katale, de fortes détonations ont semé la panique parmi les habitants, déjà éprouvés par des mois d’insécurité.\n\nAu cœur de cette escalade, des sources militaires concordantes évoquent une frappe aérienne menée par les Forces Armées de la République Démocratique du Congo. Des drones de combat auraient été déployés pour neutraliser un système de défense anti-aérien attribué au M23 et positionné sur les hauteurs stratégiques de Lumbishi.\n\nCe dispositif permettait, selon les mêmes sources, de contrôler une large portion du territoire. Sa destruction viserait à affaiblir les capacités militaires du M23 et à préparer d’éventuelles opérations d’envergure.\n\nAucun bilan officiel n’a, à ce stade, été communiqué par l’armée congolaise. De son côté, l’AFC-M23 n’a pas réagi aux sollicitations concernant ces informations.\n\nSur le terrain, la situation demeure extrêmement tendue. Les populations civiles craignent une nouvelle vague de déplacements vers des zones jugées plus sûres, dans une région déjà marquée par des déplacements massifs depuis le début du conflit.\n\nCette reprise des hostilités intervient alors que des discussions se poursuivent entre Kinshasa et les rebelles à Montreux, en Suisse. Ces pourparlers visent à trouver une issue politique à un conflit qui continue de déstabiliser l’Est de la RDC.\n\nFabien Burume', '/__l5e/assets-v1/434af40d-fc6e-4e7b-aa37-0326d4eeb61c/IMG-20260506-WA0024.jpg', NULL, '578a4dc1-5069-4500-b734-d675df9be940', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2026-05-06 14:54:52', NULL, 1, 0, 0, '#RDC | Violents affrontements à Kalehe: Lumbishi replonge da', 'Une nouvelle flambée de violences secoue le territoire de Kalehe, dans la province du Sud-Kivu. Depuis l’aube du mardi 5 mai 2026, des combats d’une intens', 0, 0, '2026-08-02 11:23:55', '2026-08-02 12:16:58'),
('afa5e9da-72c0-4d3d-81dc-c76f7b21394c', 'letat-de-siege-dans-lest-de-la-rdc-cinq-ans-apres-un-bilan-conteste', 'L’état de siège dans l’Est de la RDC: cinq ans après, un bilan contesté', 'Instauré le 6 mai 2021 par le président Félix Tshisekedi, l’état de siège dans l’Est de la République démocratique du Congo totalise aujourd’hui près de cinq années d’application. Conçue comme une réponse exceptionnelle à l’insécurité persistante, cette mesure peine toujours à…', 'Instauré le 6 mai 2021 par le président Félix Tshisekedi, l’état de siège dans l’Est de la République démocratique du Congo totalise aujourd’hui près de cinq années d’application. Conçue comme une réponse exceptionnelle à l’insécurité persistante, cette mesure peine toujours à produire les résultats escomptés.\n\nÀ l’époque, le chef de l’État justifie cette décision par une recrudescence des violences armées dans les provinces du Nord-Kivu et de l’Ituri. Plusieurs groupes rebelles, dont le Mouvement du 23 mars (M23) et les Forces démocratiques alliées, multiplient alors les attaques contre les populations civiles et les positions de l’armée.\n\nL’état de siège transfère les pouvoirs civils aux autorités militaires et policières, avec pour objectif affiché de restaurer l’autorité de l’État et de neutraliser les groupes armés.\n\nCinq ans plus tard, le constat reste préoccupant. Malgré les prorogations successives, les violences n’ont pas significativement reculé. Au contraire, les années 2025 et 2026 ont été marquées par une intensification des affrontements, notamment autour de Goma, épicentre des tensions dans le Nord-Kivu.\n\nLes déplacements massifs de populations se poursuivent, avec des milliers de civils contraints de fuir leurs villages pour se réfugier dans des camps souvent surpeuplés et précaires.\n\nDu côté des autorités, l’état de siège reste une nécessité stratégique. Le gouvernement congolais évoque une situation de « guerre imposée », pointant notamment des soutiens extérieurs présumés à certains groupes armés.\n\nPour Kinshasa, lever cette mesure reviendrait à fragiliser davantage les efforts militaires en cours et à céder du terrain face aux groupes rebelles.\n\nEn revanche, l’opposition politique et de nombreuses organisations de la société civile dressent un bilan largement critique. Elles dénoncent notamment :\n\nune efficacité limitée après cinq années d’application ;\n\ndes abus attribués à certains éléments des forces de sécurité ;\n\ndes restrictions des libertés publiques ;\n\nl’absence d’une stratégie politique globale pour résoudre durablement le conflit.\n\nCes voix appellent à un changement d’approche, privilégiant le dialogue politique, la réforme du secteur de la sécurité et la prise en compte des causes profondes de l’instabilité.\n\nAlors que la pression internationale s’accentue en faveur d’une solution durable, le débat sur une éventuelle levée de l’état de siège reste entier. Sur le terrain, cependant, la réalité quotidienne des populations civiles demeure marquée par l’insécurité, les déplacements forcés et une crise humanitaire persistante.\n\nFabien Burume', '/__l5e/assets-v1/5d35517f-cb15-4bad-b88a-2e83b9cbbc42/20260506_101156.jpg', NULL, '578a4dc1-5069-4500-b734-d675df9be940', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2026-05-06 08:45:42', NULL, 2, 0, 0, 'L’état de siège dans l’Est de la RDC: cinq ans après, un bil', 'Instauré le 6 mai 2021 par le président Félix Tshisekedi, l’état de siège dans l’Est de la République démocratique du Congo totalise aujourd’hui près de ci', 0, 0, '2026-08-02 11:23:55', '2026-08-02 12:16:58'),
('57ef243e-a8f0-4468-a64e-2ff0a89f2398', 'nyiragongo-des-chefs-coutumiers-humilies-et-contraints-de-danser-pour-les-rebelles-dans-un-camp-militaire', 'Nyiragongo: des chefs coutumiers humiliés et contraints de danser pour les rebelles dans un camp militaire', 'La coordination territoriale de la société civile de Nyiragongo a dénoncé, ce samedi 2 mai 2026, le traitement jugé « dégradant » infligé à plusieurs chefs coutumiers de la chefferie de Bukumu, transférés au centre de formation militaire de Chanzu. Selon cette organisation,…', 'La coordination territoriale de la société civile de Nyiragongo a dénoncé, ce samedi 2 mai 2026, le traitement jugé « dégradant » infligé à plusieurs chefs coutumiers de la chefferie de Bukumu, transférés au centre de formation militaire de Chanzu.\n\nSelon cette organisation, plusieurs chefs ont été contraints de chanter, danser et même de se coucher au sol dans des conditions humiliantes, avant leur transfert vers ce centre. Des pratiques qualifiées d’« inacceptables » et contraires à la dignité humaine.\n\nDans un communiqué rendu public le même jour, la société civile affirme que ces autorités traditionnelles ont été traitées « avec un mépris assimilable à celui réservé à de jeunes enfants ». Elle dénonce une « humiliation publique » et rappelle qu’aucune circonstance, quelles que soient les accusations ou controverses visant certains chefs, ne saurait justifier un tel traitement.\n\nLe document souligne par ailleurs la diversité des profils parmi les chefs concernés :\n\ncertains seraient soupçonnés de liens avec des groupes rebelles ;\n\nd’autres chercheraient à préserver leur pouvoir local ;\n\ntandis que certains font face à des contestations de légitimité liées à leur désignation par différents régimes.\n\nCes incidents surviennent dans un contexte particulièrement fragile dans le territoire de Nyiragongo, où les équilibres entre autorités traditionnelles, acteurs locaux et forces en présence demeurent précaires. Pour la société civile, c’est l’ensemble de la communauté locale qui se sent aujourd’hui atteinte par ces agissements.\n\nFabien Burume', '/__l5e/assets-v1/08bc0f0d-2157-477d-aaed-704f8203d391/20260502211657_28118492_289051294852457252_640_421_85_webp-1.png', NULL, '578a4dc1-5069-4500-b734-d675df9be940', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2026-05-04 08:01:17', NULL, 1, 0, 0, 'Nyiragongo: des chefs coutumiers humiliés et contraints de d', 'La coordination territoriale de la société civile de Nyiragongo a dénoncé, ce samedi 2 mai 2026, le traitement jugé « dégradant » infligé à plusieurs chefs', 0, 0, '2026-08-02 11:23:55', '2026-08-02 12:16:58'),
('d02af668-391c-472e-b850-442034a8988c', 'sanctions-americaines-contre-joseph-kabila-washington-prevoit-1-000000-de-recompenses-pour-toute-information-menant-a-des-violations', 'Sanctions américaines contre Joseph Kabila: Washington prévoit 1 000000$ de récompenses pour toute information menant à des violations', 'Les États-Unis ont annoncé des sanctions ciblées contre l’ancien président congolais Joseph Kabila, accusé par le Trésor américain d’avoir contribué à l’instabilité dans l’est de la République démocratique du Congo, notamment à travers un soutien présumé au M23 et à l’Alliance…', 'Les États-Unis ont annoncé des sanctions ciblées contre l’ancien président congolais Joseph Kabila, accusé par le Trésor américain d’avoir contribué à l’instabilité dans l’est de la République démocratique du Congo, notamment à travers un soutien présumé au M23 et à l’Alliance du fleuve Congo (AFC), une coalition politico-militaire engagée contre le pouvoir de Kinshasa.\n\nSelon l’Office of Foreign Assets Control (OFAC), Joseph Kabila aurait apporté un appui financier à l’AFC afin d’influencer la situation politique dans l’est du pays, encouragé des défections au sein des FARDC en faveur des rebelles et tenté de coordonner des actions contre l’armée congolaise. Washington estime également qu’il chercherait à peser sur le pouvoir central en soutenant des acteurs politiques opposés au gouvernement en place. Son séjour à Goma en 2025, sous protection du M23, est présenté comme un élément supplémentaire de proximité avec cette rébellion.\n\nLes sanctions impliquent le gel de tous les avoirs que l’ancien chef d’État pourrait détenir aux États-Unis ou via des entités américaines, ainsi qu’une interdiction générale de toute transaction avec des citoyens ou entreprises américaines. Toute structure détenue à 50 % ou plus par la personne visée est également concernée. Ces mesures exposent aussi des acteurs étrangers à des sanctions s’ils facilitent des opérations en sa faveur, renforçant ainsi son isolement financier sur le système international.\n\nWashington met un accent particulier sur la lutte contre le contournement de ces sanctions, en avertissant que toute tentative d’évasion via des intermédiaires ou des montages financiers opaques pourrait entraîner des poursuites. Dans ce cadre, les autorités américaines introduisent un levier incitatif, toute personne fournissant des informations crédibles sur des violations des sanctions peut prétendre à une récompense financière allant jusqu’à 1 000 000$. Ce mécanisme, piloté par le Financial Crimes Enforcement Network, prévoit des paiements lorsque les renseignements transmis permettent d’aboutir à des sanctions dépassant un million de dollars, une disposition qui vise à encourager les dénonciations au sein même des réseaux financiers.\n\nCette décision s’inscrit dans la stratégie de l’administration du président Donald Trump visant à faire respecter les engagements régionaux pris dans le cadre des accords de Washington de décembre 2025 entre la RDC et le Rwanda. Le secrétaire au Trésor, Scott Bessent, a affirmé que les États-Unis continueront d’utiliser tous les outils à leur disposition pour contrer les acteurs jugés responsables de l’instabilité dans l’est congolais.\n\nLes autorités américaines rappellent enfin que ces sanctions ont pour objectif de provoquer un changement de comportement et qu’une levée reste possible si la personne visée cesse toute implication dans les activités incriminées.\n\nDaniel Michombero', '/__l5e/assets-v1/a0ed673b-0998-4832-b679-ab09bcc92bcf/IMG-20260430-WA0033.jpg', NULL, '578a4dc1-5069-4500-b734-d675df9be940', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2026-04-30 20:39:57', NULL, 2, 0, 0, 'Sanctions américaines contre Joseph Kabila: Washington prévo', 'Les États-Unis ont annoncé des sanctions ciblées contre l’ancien président congolais Joseph Kabila, accusé par le Trésor américain d’avoir contribué à l’in', 0, 0, '2026-08-02 11:23:55', '2026-08-02 15:44:30'),
('c40319aa-6529-48a9-ba89-762f5aee9312', 'reelactu-plonge-au-coeur-dune-prison-souterraine-erigee-par-m23-dans-la-ville-de-goma', 'Reelactu plonge au cœur d’une prison souterraine érigée par M23 dans la ville de Goma', 'Révélations d’un journaliste rescapé des geôles souterraines du M23 Un journaliste récemment libéré des mains du M23 s’est confié vendredi 10 octobre à Reelactu, il livre un témoignage glaçant sur les atrocités commises dans les prisons souterraines de la rébellion, en pleine…', 'Révélations d’un journaliste rescapé des geôles souterraines du M23\n\nUn journaliste récemment libéré des mains du M23 s’est confié vendredi 10 octobre à Reelactu, il livre un témoignage glaçant sur les atrocités commises dans les prisons souterraines de la rébellion, en pleine ville de Goma, occupée par ce mouvement armé depuis janvier. Son récit, à la fois bouleversant et effrayant, met à nu l’enfer que subissent quotidiennement les habitants tombés entre les mains des rebelles.\n\n« Nous étions 80 personnes, tous des hommes, dans un espace de trois mètres carrés », raconte-t-il d’une voix encore tremblante. « En sept jours, j’ai vécu un calvaire que je n’aurais jamais imaginé. »\n\nDès leur arrivée, les prisonniers subissent ce que les rebelles appellent une “séance d’admission”. Quatre hommes, postés à l’entrée, accueillent chaque détenu à coups de fouets, sans distinction. Deux tiennent la tête, deux les jambes, tandis que les lanières s’abattent avec brutalité.\n\n« Si vous êtes soupçonné de collaborer avec le gouvernement ou les FARDC, c’est entre la vie et la mort », confie le journaliste.\n\nÀ l’intérieur, les conditions sont inhumaines. Pas de visite, pas de soins, pas de nourriture venant de l’extérieur. Les prisonniers survivent à une seule ration quotidienne composée de maïs et de haricots, souvent sans huile ni sel. L’air est irrespirable.\n\n« Certains meurent à l’intérieur, les corps dégagent une odeur insoutenable », témoigne-t-il.\n\nChaque matin, des gardiens, tous des combattants du M23, viennent « choisir » des détenus pour de nouvelles séances de torture. « Ils prennent ceux qui tiennent encore debout pour les frapper encore. »\n\nLe journaliste dénonce aussi une ségrégation ethnique au sein de ces prisons clandestines.\n\n« Durant mon séjour, je n’ai jamais vu un seul Tutsi enfermé. Tous les détenus étaient issus d’autres communautés. »\n\nLe sort des prisonniers dépend de la nature des accusations. Ceux soupçonnés de collaboration avec les forces loyalistes, les Wazalendo, les FDLR ou les autorités de Kinshasa, n’ont presque aucune chance de survie. Beaucoup meurent sur place, d’autres seraient transférés vers une autre prison du M23 à Rutshuru, d’où peu reviennent.\n\nLe journaliste, lui, ne doit sa liberté qu’à une improbable rencontre.\n\n« Un homme m’a reconnu, il se souvenait que je l’avais aidé un jour à Rubaya. C’est grâce à lui que j’ai pu sortir, sinon j’y aurais laissé ma peau », raconte-t-il.\n\nMais même libre, la peur le poursuit.\n\n« Il m’a conseillé de ne pas me montrer. Celui qui avait ordonné mon arrestation a été muté à Bukavu. Mais je ne suis plus en sécurité. »\n\nCe témoignage vient confirmer les multiples alertes des organisations locales et internationales sur les graves violations des droits humains dans les zones sous contrôle du M23, soutenu par le Rwanda selon Kinshasa et plusieurs rapports onusiens.\n\nPendant que la communauté internationale multiplie les appels à un cessez-le-feu, la population de Goma, elle, continue de vivre sous la terreur. Et dans les prisons souterraines de la rébellion, la mort rôde, silencieuse.', '/__l5e/assets-v1/e7604c61-0c9c-418b-9661-c9eefb2e2df0/8771e9c0-84cb-4b24-8b6e-61d667762c7f.jpeg', NULL, 'fe9719a8-01fe-4ec7-a344-f81db679f2d6', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2025-10-11 17:50:13', NULL, 2, 0, 0, 'Reelactu plonge au cœur d’une prison souterraine érigée par ', 'Révélations d’un journaliste rescapé des geôles souterraines du M23 Un journaliste récemment libéré des mains du M23 s’est confié vendredi 10 octobre à Ree', 0, 0, '2026-08-02 11:23:55', '2026-08-04 16:32:18'),
('6aeabd89-d5cd-4b80-9f9e-9d7016dbe693', '10-jours-dans-trois-prisons-du-m23-a-goma-emmanuel-raconte-lenfer-des-conteneurs-et-des-prisonniers-tues-a-coups-de-fouet', '10 jours dans trois prisons du M23 à Goma: Emmanuel raconte l’enfer des conteneurs et des prisonniers tués à coups de fouet', 'Depuis un an, la ville de Goma est sous le contrôle du M23, une rébellion soutenue par le Rwanda. Derrière les discours officiels, des civils racontent un autre visage de l’occupation. Emmanuel, nom d’emprunt pour protéger sa famille est un pasteur d’une église chrétienne. Il…', 'Depuis un an, la ville de Goma est sous le contrôle du M23, une rébellion soutenue par le Rwanda. Derrière les discours officiels, des civils racontent un autre visage de l’occupation.\n\nEmmanuel, nom d’emprunt pour protéger sa famille est un pasteur d’une église chrétienne. Il dit avoir passé dix jours dans trois prisons différentes contrôlées par les rebelles du M23. Il livre un témoignage brut.\n\n« Le morceau de viande n’a jamais atteint ma bouche »\n\n« Nous étions au salon en train de manger avec les enfants. 8 militaires armés ont fait irruption. Une seule question m’a été posée, elle a scellé mon sort : “Tu es le père de ces enfants ?” J’ai répondu oui. C’est tout. »\n\nIl marque un silence.\n\n« Le morceau de viande que j’avais en main n’a jamais atteint ma bouche. Ils ont directement ligoté mes mains. Mes téléphones et pièces d’identités directement confisquées »\n\n12 autres hommes entrent. Ma maison n’a que deux chambres, ell a été fouillée, les objets jetés dehors. Rien de compromettant n’a été trouvé.\n\n« Le gradé m’a demandé si j’avais des effets militaires. J’ai dit non. Il m’a demandé si j’avais des relations avec Kinshasa. J’ai dit non. »\n\nDehors, la parcelle est quadrillée. Puis l’ordre tombe.\n\n« Quatre militaires m’ont soulevé et jeté comme un colis dans la jeep. Ma tête était coincée dans leurs bottes militaires… puantes. Je respirais cette odeur pendant tout le trajet. Nous avons roulé plus de six heures. »\n\nKituku : « Nous avons dormi sur les morts »\n\nArrivée vers 2h du matin à Kituku.\n\n« Si l’enfer existe, il ressemble à ce que j’ai vu cette nuit-là. »\n\nDans une concession privée, six conteneurs servent de prisons. Emmanuel est jeté dans l’un d’eux.\n\n« J’étais le 52e à l’intérieur. Pas de fenêtre, difficile à respirer à l’intérieur. Une odeur insupportable. Deux hommes à côté de moi avaient le corps gonflé, ils avaient été sévèrement battus selon les autres prisonniers. Ils sont morts dans la nuit. Après s’être battus contre la mort, jetant les pieds et les bras bouche grandement ouverte »\n\n« Faute d’espace, Nous avons dormi sur leurs corps », explique Emmanuel larmes aux yeux.\n\n« Les cadavres seront ensuite emportés la nuit suivante en pirogue en bois vers le lac Kivu, affirme-t-il.\n\n« Ils m’ont frappé sur les parties intimes »\n\nLe lendemain, il est appelé avec un autre détenu.\n\n« Six militaires m’ont battu. Chacun utilisait ce qu’il voulait. Je me souviens qu’on m’a frappé avec un objet métallique sur les parties intimes. J’ai perdu connaissance. »\n\nIl dit avoir craché du sang, incapable de lever la main pour manger.\n\n« La nourriture était là haricots et riz, j’avais tellement faim mais mes mains ne pouvaient pas atteindre ma bouche. Elles ont été sérieusement tabassées »\n\nÀ Kituku, selon lui, « on mange deux fois par jour et on est fouetté deux fois par jour ».\n\nAprès trois jours dans ces conditions, il est transféré à la prison de la 8e région militaire, sans qu’aucune accusation ne lui soit notifiée.\n\nDeuxième prison : « Au moins, il y avait de l’air »\n\nÀ la 8e région militaire, non loin du rond-point Cercle Sportif, les conteneurs ont des fenêtres, mais les fouets continuent.\n\n« J’ai respiré pendant trois jours. Mais on battait toujours les gens. »\n\nPuis nouveau transfert vers Mont Goma.\n\nMont Goma : « J’ai vu six personnes mourir en cinq jours »\n\nDans ce troisième site, six prisons fonctionnent en conteneurs.\n\n« J’ai été battu par des détenus, puis par des militaires. En cinq jours, six personnes sont mortes. Certains après les coups. D’autres avec des plaies infectées. »\n\nLe cinquième jour, le gouverneur rebelle Bahati Erasto arrive pour désengorger les cellules, raconte Emmanuel.\n\nLes détenus sont classés en quatre catégories : innocents, petits conflits, dettes, criminels à transférer.\n\n« J’ai été mis parmi les innocents. Sur environ 150 détenus, nous étions 13 à ne pas être battus. »\n\nPuis il décrit une scène qu’il dit ne jamais pouvoir oublier :\n\n« Les autres ont été battus devant le gouverneur. Au moins 45 militaires frappaient. J’ai vu des gens perdre les yeux. D’autres avaient les oreilles cassées. Certains étaient défigurés. »\n\nCertains libérés auraient choisi d’aller d’abord à l’hôpital, dit-il, « pour ne pas effrayer leurs enfants ».\n\n« Je n’ai jamais su pourquoi j’étais arrêté »\n\nAu total, Emmanuel affirme avoir passé dix jours entre Kituku, la 8e région et Mont Goma.\n\n« Je n’ai jamais su l’infraction. On ne m’a jamais expliqué. »\n\nUne semaine après sa libération, il quitte Goma, transitant par le Rwanda avant de rejoindre Beni.\n\nSon récit s’ajoute aux accusations d’arrestations arbitraires, de détentions extrajudiciaires et de sévices dans les zones sous contrôle du M23.\n\nDans une ville occupée depuis un an, Emmanuel résume ainsi son expérience :\n\n« Ce n’était pas une prison. C’était un endroit où l’on attendait de mourir. »\n\nDaniel Michombero', '/__l5e/assets-v1/565efb63-4ee0-4182-b14f-c5340db10649/20260301_183335.jpg', NULL, 'fe9719a8-01fe-4ec7-a344-f81db679f2d6', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2026-03-01 20:57:12', NULL, 4, 0, 0, '10 jours dans trois prisons du M23 à Goma: Emmanuel raconte ', 'Depuis un an, la ville de Goma est sous le contrôle du M23, une rébellion soutenue par le Rwanda. Derrière les discours officiels, des civils racontent un ', 0, 0, '2026-08-02 11:23:55', '2026-08-04 16:32:18'),
('fcc23839-debd-4c04-bde1-9e4254519820', 'rdc-a-uvira-la-justice-militaire-reprend-ses-audiences-apres-5-mois-de-crise', 'RDC: à Uvira, la justice militaire reprend ses audiences après 5 mois de crise', 'À Uvira, dans l’est de la République démocratique du Congo, les activités judiciaires reprennent ce jeudi 30 avril, marquant une étape importante après plusieurs semaines d’instabilité et d’absence d’institutions fonctionnelles. La ville avait été occupée par les rebelles du M23…', 'À Uvira, dans l’est de la République démocratique du Congo, les activités judiciaires reprennent ce jeudi 30 avril, marquant une étape importante après plusieurs semaines d’instabilité et d’absence d’institutions fonctionnelles.\n\nLa ville avait été occupée par les rebelles du M23 le 10 décembre 2025, avant leur retrait en janvier 2026. Durant cette période, Uvira est restée sans appareil judiciaire opérationnel, dans un contexte de violences, de pillages et de nombreuses atteintes aux droits humains.\n\nAu tribunal militaire d’Uvira, les premières audiences concernent notamment des éléments Wazalendo, ces combattants locaux engagés aux côtés de l’armée congolaise. Ces procès publics visent à lutter contre l’impunité et à rétablir l’autorité de l’État.\n\nDans les quartiers, les habitants tentent progressivement de reprendre une vie normale après des semaines marquées par l’insécurité et l’absence de recours judiciaire. Par ailleurs, 470 personnes sont de retour de camps de réfugiés au Burundi, avec l’appui du Haut Commissariat des Nations unies pour les réfugiés, réintègrent une ville encore fragilisée.\n\nMalgré cette reprise, la situation sécuritaire demeure préoccupante. Des positions de groupes armés sont toujours signalées à proximité d’Uvira, entretenant un climat de tension.\n\nLes autorités et les acteurs de la société civile espèrent que le retour de la justice contribuera à stabiliser durablement la ville, même si de nombreux défis restent à relever pour restaurer pleinement la confiance de la population.\n\nFabien Burume', '/__l5e/assets-v1/2f0d99b7-645e-456c-bbd0-d6ff4349da54/IMG-20260429-WA0033-1.jpg', NULL, '578a4dc1-5069-4500-b734-d675df9be940', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2026-04-29 16:37:17', NULL, 1, 0, 0, 'RDC: à Uvira, la justice militaire reprend ses audiences apr', 'À Uvira, dans l’est de la République démocratique du Congo, les activités judiciaires reprennent ce jeudi 30 avril, marquant une étape importante après plu', 0, 0, '2026-08-02 11:23:55', '2026-08-02 12:16:58'),
('a93da95b-79b5-47b2-ae85-82fea8d6abcb', 'sante-en-rdc-les-gouverneurs-sommes-dagir-pour-la-couverture-sante-universelle', 'Santé en RDC: les gouverneurs sommés d’agir pour la Couverture Santé Universelle', 'La 12ᵉ Conférence des gouverneurs s’est clôturée sur une note d’urgence et de responsabilité. Dans un discours sans détour, le Vice-Premier ministre en charge de l’Intérieur, Jacquemain Shabani, a lu les recommandations de la Commission Santé, appelant les provinces à une…', 'La 12ᵉ Conférence des gouverneurs s’est clôturée sur une note d’urgence et de responsabilité. Dans un discours sans détour, le Vice-Premier ministre en charge de l’Intérieur, Jacquemain Shabani, a lu les recommandations de la Commission Santé, appelant les provinces à une mobilisation collective pour transformer les promesses de la Couverture Santé Universelle (CSU) en actions concrètes.\n\nParmi les priorités, l’augmentation du budget de la santé à 15 % au niveau national et provincial est jugée incontournable. Ce financement devra appuyer des domaines critiques comme la lutte contre le VIH pédiatrique, la nutrition, la vaccination et la réponse aux épidémies. Chaque province est ainsi appelée à décaisser au moins un million de dollars pour ces urgences sanitaires.\n\nAutre mesure phare : l’identification de financements innovants et domestiques pour soutenir durablement l’extension de la CSU dans les 26 provinces. L’État attend des provinces la soumission de projets bancables à la Caisse nationale de péréquation pour le développement d’industries pharmaceutiques locales.\n\nLe plaidoyer insiste également sur la mise en place de mutuelles de santé et d’une assurance maladie obligatoire, élargies à toute la population. Objectif : assurer des mécanismes efficaces de partage des risques et garantir un accès équitable aux soins, notamment pour les enfants.\n\nCôté ressources humaines, le message est clair : recruter et affecter le personnel de santé manquant sur base des besoins réels exprimés par les provinces, tout en respectant les textes légaux et réglementaires. Le VPM Shabani a aussi appelé à la restructuration des mécanismes de concertation entre le gouvernement central et les entités décentralisées, par le biais du Comité national de pilotage.\n\nEnfin, la Commission Santé exhorte à l’opérationnalisation de l’approche « One Health Une seule santé », via des comités multisectoriels. La lutte contre la malnutrition chronique devra mobiliser des interventions coordonnées entre santé, éducation, agriculture, pêche et affaires sociales.\n\nDans un pays où les inégalités d’accès aux soins restent criantes, ces recommandations marquent un tournant. Mais tout dépendra, selon les observateurs, de la volonté politique des provinces à transformer les engagements de Kolwezi en résultats palpables dans les zones les plus reculées.\n\n« Il ne s’agit plus de déclarations d’intention. Le temps est venu de passer à l’action pour sauver des vies, » a conclu Jacquemain Shabani, sous les applaudissements des gouverneurs réunis.\n\nDaniel Michombero', '/__l5e/assets-v1/b4d6b985-daf1-45f7-8209-75470bc1c96b/DSC_0013.jpg', NULL, '483c6016-e901-488d-ba50-48aad757557c', '54e75780-b018-4965-935b-7752e055847c', NULL, 'publie', '2025-06-14 17:31:43', NULL, 2, 0, 0, 'Santé en RDC: les gouverneurs sommés d’agir pour la Couvertu', 'La 12ᵉ Conférence des gouverneurs s’est clôturée sur une note d’urgence et de responsabilité. Dans un discours sans détour, le Vice-Premier ministre en cha', 0, 0, '2026-08-02 11:23:55', '2026-08-02 15:44:30'),
('738b4821-94ad-42e4-b317-0d600c978cdb', '10-jours-dans-trois-prisons-du-m23-a-goma', '10 jours dans trois prisons du M23 à Goma', '10 jours dans trois prisons du M23 à Goma : Emmanuel raconte l’enfer des conteneurs et des prisonniers tués à coups de fouet Depuis un an, la ville de Goma est sous le contrôle du M23, une rébellion soutenue par le Rwanda. Derrière les discours officiels, des civils racontent un…', '10 jours dans trois prisons du M23 à Goma : Emmanuel raconte l’enfer des conteneurs et des prisonniers tués à coups de fouet\n\nDepuis un an, la ville de Goma est sous le contrôle du M23, une rébellion soutenue par le Rwanda. Derrière les discours officiels, des civils racontent un autre visage de l’occupation.\n\nEmmanuel, nom d’emprunt pour protéger sa famille est un pasteur d’une église chrétienne. Il dit avoir passé dix jours dans trois prisons différentes contrôlées par les rebelles du M23. Il livre un témoignage brut.\n\n« Le morceau de viande n’a jamais atteint ma bouche »\n\n« Nous étions au salon en train de manger avec les enfants. 8 militaires armés ont fait irruption. Une seule question m’a été posée, elle a scellé mon sort : “Tu es le père de ces enfants ?” J’ai répondu oui. C’est tout. »\n\nIl marque un silence.\n\n« Le morceau de viande que j’avais en main n’a jamais atteint ma bouche. Ils ont directement ligoté mes mains. Mes téléphones et pièces d’identités directement confisquées »\n\n12 autres hommes entrent. Ma maison n’a que deux chambres, ell a été fouillée, les objets jetés dehors. Rien de compromettant n’a été trouvé.\n\n« Le gradé m’a demandé si j’avais des effets militaires. J’ai dit non. Il m’a demandé si j’avais des relations avec Kinshasa. J’ai dit non. »\n\nDehors, la parcelle est quadrillée. Puis l’ordre tombe.\n\n« Quatre militaires m’ont soulevé et jeté comme un colis dans la jeep. Ma tête était coincée dans leurs bottes militaires… puantes. Je respirais cette odeur pendant tout le trajet. Nous avons roulé plus de six heures.