SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

DROP TABLE IF EXISTS `categories`;
CREATE TABLE `categories` (
  `id` CHAR(36) NOT NULL,
  `slug` VARCHAR(255) NOT NULL,
  `name` LONGTEXT NOT NULL,
  `kind` LONGTEXT NOT NULL,
  `parent_id` CHAR(36) NULL,
  `position` INT NOT NULL,
  `description` LONGTEXT NULL,
  `created_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `authors`;
CREATE TABLE `authors` (
  `id` CHAR(36) NOT NULL,
  `user_id` CHAR(36) NULL,
  `slug` VARCHAR(255) NOT NULL,
  `display_name` LONGTEXT NOT NULL,
  `role_label` LONGTEXT NULL,
  `bio` LONGTEXT NULL,
  `avatar_url` LONGTEXT NULL,
  `city` LONGTEXT NULL,
  `twitter` LONGTEXT NULL,
  `linkedin` LONGTEXT NULL,
  `email` LONGTEXT NULL,
  `created_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tags`;
CREATE TABLE `tags` (
  `id` CHAR(36) NOT NULL,
  `slug` VARCHAR(255) NOT NULL,
  `name` LONGTEXT NOT NULL,
  `created_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `articles`;
CREATE TABLE `articles` (
  `id` CHAR(36) NOT NULL,
  `slug` VARCHAR(255) NOT NULL,
  `title` LONGTEXT NOT NULL,
  `dek` LONGTEXT NULL,
  `body` LONGTEXT NOT NULL,
  `cover_url` LONGTEXT NULL,
  `cover_credit` LONGTEXT NULL,
  `category_id` CHAR(36) NULL,
  `author_id` CHAR(36) NULL,
  `created_by` CHAR(36) NULL,
  `status` ENUM('brouillon','relecture','valide','publie') NOT NULL,
  `published_at` DATETIME NULL,
  `location` LONGTEXT NULL,
  `reading_minutes` INT NOT NULL,
  `is_featured` TINYINT(1) NOT NULL,
  `is_breaking` TINYINT(1) NOT NULL,
  `seo_title` LONGTEXT NULL,
  `seo_description` LONGTEXT NULL,
  `view_count` INT NOT NULL,
  `share_count` INT NOT NULL,
  `created_at` DATETIME NOT NULL,
  `updated_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `article_categories`;
CREATE TABLE `article_categories` (
  `article_id` CHAR(36) NOT NULL,
  `category_id` CHAR(36) NOT NULL,
  PRIMARY KEY (`article_id`, `category_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `article_tags`;
CREATE TABLE `article_tags` (
  `article_id` CHAR(36) NOT NULL,
  `tag_id` CHAR(36) NOT NULL,
  PRIMARY KEY (`article_id`, `tag_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `app_settings`;
CREATE TABLE `app_settings` (
  `key` VARCHAR(255) NOT NULL,
  `value` JSON NOT NULL,
  `updated_at` DATETIME NOT NULL,
  PRIMARY KEY (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `social_publications`;
CREATE TABLE `social_publications` (
  `id` CHAR(36) NOT NULL,
  `article_id` CHAR(36) NOT NULL,
  `platform` VARCHAR(255) NOT NULL,
  `status` LONGTEXT NOT NULL,
  `message` LONGTEXT NULL,
  `post_url` LONGTEXT NULL,
  `error` LONGTEXT NULL,
  `sent_at` DATETIME NULL,
  `created_at` DATETIME NOT NULL,
  `updated_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `share_events`;
CREATE TABLE `share_events` (
  `id` CHAR(36) NOT NULL,
  `article_slug` VARCHAR(255) NOT NULL,
  `network` VARCHAR(255) NOT NULL,
  `referrer` LONGTEXT NULL,
  `created_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `direct_events`;
CREATE TABLE `direct_events` (
  `id` CHAR(36) NOT NULL,
  `kind` LONGTEXT NOT NULL,
  `severity` LONGTEXT NOT NULL,
  `reason` LONGTEXT NULL,
  `age_minutes` INT NULL,
  `breaking_count` INT NULL,
  `ticker_items` INT NULL,
  `duration_ms` INT NULL,
  `db_error` LONGTEXT NULL,
  `path` LONGTEXT NULL,
  `detail` JSON NULL,
  `created_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `user_roles`;
CREATE TABLE `user_roles` (
  `id` CHAR(36) NOT NULL,
  `user_id` CHAR(36) NOT NULL,
  `role` ENUM('admin','directeur_publication','redacteur_chef','editeur','journaliste','correcteur','photographe','videaste','community_manager') NOT NULL,
  `created_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS=1;